-- Cave of Altamira
INSERT INTO Language_en_US 
			(Tag,									Text) 
VALUES		('TXT_KEY_BUILDING_ALTAMIRA',			'Cave of Altamira'),
			('TXT_KEY_WONDER_ALTAMIRA_QUOTE',		'[NEWLINE]"After Altamira everything seems decadent."[NEWLINE] - Pablo Picasso[NEWLINE]'),
			('TXT_KEY_BUILDING_ALTAMIRA_PEDIA',		'The Cave of Altamira, located near Santillana del Mar in Cantabria, northern Spain, is one of the most celebrated prehistoric art sites in the world. Discovered in 1868 by a local hunter and later studied in detail after 1879 when amateur archaeologist Marcelino Sanz de Sautuola recognized its significance, the cave gained international attention for its vivid Paleolithic paintings. These artworks, created between 36,000 and 14,000 years ago, showcase the skill and imagination of Upper Paleolithic peoples. Initially, many scholars doubted their authenticity, claiming prehistoric humans lacked the sophistication to produce such works. However, further discoveries of similar cave art across Europe confirmed their legitimacy, and Altamira became a cornerstone in the study of human cultural and artistic development. [NEWLINE][NEWLINE]The cave itself stretches about 1,000 meters  (3,280.84 ft), though the decorated section—often called the "Sistine Chapel of Prehistory"—focuses on a main chamber with polychrome paintings of bison, horses, deer, and abstract signs. Artists used natural pigments such as ochre, hematite, and charcoal, often utilizing the cave''s contours to give the animals a sense of three-dimensionality and movement. These works likely served symbolic, ritual, or spiritual purposes rather than being mere decoration. Today, the original cave is closed to regular public visits to preserve the fragile paintings from damage caused by humidity and human presence, but a faithful replica exists at the Altamira Museum, allowing visitors to experience the wonder of this prehistoric masterpiece while safeguarding its legacy for future generations.'),
			('TXT_KEY_BUILDING_ALTAMIRA_HELP',		'');

INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_ALTAMIRA_HELP_CUT', '[COLOR_YIELD_FOOD]Cave of Altamira[ENDCOLOR] is an ideal hiding spot (+1[ICON_STRENGTH]) and greatly supports early culture shaping (+1[ICON_CULTURE]), especially, if you find herds of [COLOR_GREY]Bisons[ENDCOLOR], [COLOR_GREY]Deers[ENDCOLOR] or [COLOR_GREY]Horses[ENDCOLOR] (+1[ICON_FOOD], +1[ICON_CULTURE]/[ICON_RES_BISON][ICON_RES_BISON], [ICON_RES_DEER][ICON_RES_DEER], [ICON_RES_HORSE][ICON_RES_HORSE]). Maximize its effectiveness by painting the interior of the cave with outstanding pictures (+1[ICON_GW_ART]) or by rushing advanced technologies ([COLOR_CYAN]Archaeology[ENDCOLOR]: +3[ICON_CULTURE]).');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Mountain (range 2)[ENDCOLOR][NEWLINE][ICON_BULLET]Improved Resource: [ICON_RES_BISON]/[ICON_RES_DEER]/[ICON_RES_HORSE]'||Text WHERE Tag ='TXT_KEY_BUILDING_ALTAMIRA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Improved Resource: [ICON_RES_BISON]/[ICON_RES_DEER]/[ICON_RES_HORSE]'||Text WHERE Tag ='TXT_KEY_BUILDING_ALTAMIRA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
