-- Ggantija
INSERT INTO Language_en_US 
			(Tag,									Text) 
VALUES		('TXT_KEY_BUILDING_GGANTIJA',			'Ggantija'), /*Ġgantija*/
			('TXT_KEY_WONDER_GGANTIJA_QUOTE',		'[NEWLINE]"We need to find God, and he cannot be found in noise and restlessness. God is the friend of silence. See how nature - trees, flowers, grass - grows in silence; see the stars, the moon and the sun, how they move in silence... We need silence to be able to touch souls."[NEWLINE] - Mother Teresa[NEWLINE]'),
			('TXT_KEY_BUILDING_GGANTIJA_PEDIA',		'Ggantija, located on the island of Gozo in Malta, is one of the world''s oldest free-standing structures, predating Stonehenge and the Egyptian pyramids. Built during the Neolithic period, around 3600–3200 BCE, it is part of the UNESCO World Heritage–listed Megalithic Temples of Malta. The name Ggantija, meaning "giantess" in Maltese, comes from local folklore that attributed the massive construction to giants, as the colossal stones seemed too heavy for ordinary humans to move. Archaeological studies, however, show that the temples were erected by early farming communities who developed advanced knowledge of construction techniques, ritual practices, and social organization thousands of years ago. [NEWLINE][NEWLINE]The site consists of two adjoining temple structures enclosed within a boundary wall, built with huge limestone blocks, some weighing over 50 tons. The temples feature a cloverleaf layout with apses, altars, and evidence of ritual use, such as animal bones and offerings found during excavations. Their design suggests they were places of communal worship and fertility rituals, possibly dedicated to a mother goddess figure, as indicated by the discovery of figurines and symbolic carvings. Despite their great age, the temples remain remarkably well-preserved, showcasing the ingenuity and spiritual life of Malta''s prehistoric inhabitants. Today, Ggantija is a major archaeological landmark, offering visitors a glimpse into humanity''s earliest monumental architecture.'),
			('TXT_KEY_BUILDING_GGANTIJA_HELP',		'');

INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_GGANTIJA_HELP_CUT', '[COLOR_YIELD_FOOD]Ggantija[ENDCOLOR]''s construction, inspired by the cult of fertility, brings a prosperity to your empire and instantly boosts its growth (50[ICON_FOOD]) and increases the efficiency of all [COLOR_CITY_BROWN]Farms[ENDCOLOR] (+1[ICON_FOOD]/[COLOR_CITY_BROWN]Tile in Empire[ENDCOLOR]). Therefore, to develop your city even more, it is advised to found a religion as soon as possible (+2[ICON_PEACE]; 10%[ICON_PEACE] into [ICON_FOOD]).');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Grassland[ENDCOLOR][NEWLINE][ICON_BULLET]Improvement: [COLOR_CYAN]2 Farms[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_GGANTIJA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Grassland[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_GGANTIJA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
----------------------------------------------------				
-- Goebekli Tepe	
INSERT INTO Language_en_US 
			(Tag,										Text) 
VALUES		('TXT_KEY_BUILDING_GOEBEKLI_TEPE',			'Göbekli Tepe'),
			('TXT_KEY_WONDER_GOEBEKLI_TEPE_QUOTE',		'[NEWLINE]"Look up at the stars and not down at your feet. Try to make sense of what you see, and wonder about what makes the universe exist. Be curious."[NEWLINE] - Stephen Hawking[NEWLINE]'),
			('TXT_KEY_BUILDING_GOEBEKLI_TEPE_PEDIA',	'Göbekli Tepe, located in southeastern Turkey near the city of Şanliurfa, is considered the world''s oldest known temple complex, dating back to around 9600–9500 BCE, thousands of years before Stonehenge or the Egyptian pyramids. Discovered in the 1960s and excavated in earnest from the 1990s onward, it dramatically reshaped our understanding of prehistoric societies. The site was built by hunter-gatherer communities at the end of the last Ice Age, challenging the traditional view that organized religion and monumental architecture only emerged after the advent of farming. Archaeologists believe the structures served as a gathering place for ritual and social activities, making Göbekli Tepe a focal point of early human culture and spirituality. [NEWLINE][NEWLINE]The site consists of multiple circular and oval enclosures formed by massive T-shaped limestone pillars, some reaching up to 5.5 meters in height and weighing several tons. Many of these pillars are decorated with intricate carvings of animals such as lions, snakes, wild boars, and birds, as well as abstract symbols, suggesting a rich symbolic and mythological system. Unlike later temples, Göbekli Tepe shows no evidence of domestic life, supporting the idea that it was purely ceremonial. The site was deliberately buried by its builders around 8000 BCE, which helped preserve it for millennia. Today, Göbekli Tepe stands as one of archaeology''s most significant discoveries, offering profound insights into the origins of religion, art, and social complexity.'),
			('TXT_KEY_BUILDING_GOEBEKLI_TEPE_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_GOEBEKLI_TEPE_HELP_CUT', '[COLOR_YIELD_FOOD]Göbekli Tepe[ENDCOLOR] is an excellent choice for a [COLOR_CITY_BLUE]Mountainous[ENDCOLOR] area (+1[ICON_PEACE]/[COLOR_CITY_BLUE]Tile[ENDCOLOR]). It is a multi-purpose building (+1[ICON_RESEARCH]; +1[ICON_CULTURE]; +1[ICON_PEACE]), but it cannot be forgotten that excavation of [COLOR_GREY]Stone[ENDCOLOR] (+1[ICON_RESEARCH]/[ICON_RES_STONE][ICON_RES_STONE]) used for construction of this unusual [COLOR_YIELD_FOOD]Shrine[ENDCOLOR] (+1[ICON_RESEARCH][ICON_RESEARCH]), and probably many others in future, should be a priority for such a progressive emperor.');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Mountain (range 2)[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_NEGATIVE_TEXT]Water[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_GOEBEKLI_TEPE_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Mountain (range 2)[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_GOEBEKLI_TEPE_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
