-- Majorville Medicine Wheel
INSERT INTO Language_en_US 
			(Tag,									Text) 
VALUES		('TXT_KEY_BUILDING_MAJORVILLE',			'Majorville Medicine Wheel'), /*Iniskim Umaapi*/
			('TXT_KEY_WONDER_MAJORVILLE_QUOTE',		'[NEWLINE]"When the Earth is sick, the animals will begin to disappear, when that happens, The Warriors of the Rainbow will come to save them."[NEWLINE] - Chief Seattle[NEWLINE]'),
			('TXT_KEY_BUILDING_MAJORVILLE_PEDIA',	'The Majorville Medicine Wheel, located in southern Alberta, Canada within the Blackfoot Nation, is one of the largest and oldest known medicine wheels in North America. Estimated to be over 4,500 years old, it predates the Great Pyramids of Giza and Stonehenge, making it one of the longest continuously used sacred sites on the continent. Built and maintained by Indigenous peoples, the wheel served spiritual, ceremonial, and astronomical purposes across countless generations. Archaeological studies suggest that it was not constructed all at once but developed gradually over millennia, with offerings and cairns added during different periods of occupation. Its longevity and cultural importance highlight the continuity of Indigenous traditions on the Northern Plains. [NEWLINE][NEWLINE]The structure consists of a large central cairn surrounded by a stone circle nearly 27 meters in diameter, with 28 radial lines extending outward, resembling the spokes of a wheel. This design is believed to align with celestial events such as solstices and equinoxes, suggesting that it may have functioned as both a ceremonial and astronomical site. Artifacts including stone tools and offerings found at the site indicate that it was a place of ritual gatherings, vision quests, and spiritual observances tied to the cycles of nature. Today, the Majorville Medicine Wheel remains an active sacred site for Indigenous communities, while also serving as a powerful reminder of the deep connections between spirituality, astronomy, and landscape in ancient North America.'),
			('TXT_KEY_BUILDING_MAJORVILLE_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_MAJORVILLE_HELP_CUT', '[COLOR_YIELD_FOOD]Majorville Medicine Wheel[ENDCOLOR] strongly supports religious development in unpleasant cold [COLOR_CITY_BLUE]Tundra[ENDCOLOR] regions (+1[ICON_PEACE]/[COLOR_CITY_BLUE]Tile[ENDCOLOR]). Its unbelievably strong scientific pattern emanates (+1[ICON_RESEARCH]) influencing numerous creatures under your control, and improving all your [COLOR_CITY_BROWN]Camps[ENDCOLOR] (+1[ICON_FOOD]/[COLOR_CITY_BROWN]Tile in Empire[ENDCOLOR]) and [COLOR_GREY]Bisons[ENDCOLOR] (+1[ICON_CULTURE]/[ICON_RES_BISON][ICON_RES_BISON]).');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Tundra[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_MAJORVILLE_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Tundra[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_MAJORVILLE_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
