-- Mohenjo-daro
INSERT INTO Language_en_US 
			(Tag,										Text) 
VALUES		('TXT_KEY_BUILDING_MOHENJO_DARO',			'Mohenjo-daro'),
			('TXT_KEY_WONDER_MOHENJO_DARO_QUOTE',		'[NEWLINE]"A river is an ocean in a desert."[NEWLINE] - Matshona Dhliwayo[NEWLINE]'),
			('TXT_KEY_BUILDING_MOHENJO_DARO_PEDIA',		'Mohenjo-daro, located in present-day Sindh, Pakistan, was one of the principal urban centers of the Indus Valley Civilization, which flourished between 2600 and 1900 BCE. Discovered in the 1920s during British-led excavations, it revealed a highly advanced city that rivaled contemporary civilizations in Mesopotamia and Egypt. The name "Mohenjo-daro" means "Mound of the Dead" in Sindhi, reflecting its ruinous state when first unearthed. Archaeological evidence suggests that the city was carefully planned, with streets laid out in a grid pattern, standardized baked-brick construction, and an impressive drainage and water management system—one of the earliest of its kind in human history. Its discovery reshaped the understanding of South Asia''s ancient past, proving that complex urban societies developed independently in the region. [NEWLINE][NEWLINE]The city covered several hundred hectares and may have supported tens of thousands of inhabitants at its peak. Its notable structures include the Great Bath, likely used for ritual purification, granaries for food storage, assembly halls, and residential areas divided into well-organized blocks. Artifacts such as seals, pottery, figurines, and tools reveal a rich cultural and economic life, with evidence of trade extending as far as Mesopotamia. Strikingly, no large palaces or temples have been found, suggesting a social structure that differed from other early civilizations, possibly more egalitarian or organized through communal governance. Today, Mohenjo-daro is a UNESCO World Heritage Site, though it faces threats from erosion, flooding, and human activity, making its preservation a global priority.'),
			('TXT_KEY_BUILDING_MOHENJO_DARO_HELP',		'');

INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_MOHENJO_DARO_HELP_CUT', '[COLOR_YIELD_FOOD]Mohenjo-daro[ENDCOLOR] thanks to numerous quality of life features makes existence over [COLOR_CITY_GREEN]River[ENDCOLOR] much easier than before (+2[ICON_FOOD]; +1[ICON_FOOD]/[COLOR_CITY_GREEN]Tile[ENDCOLOR]). Induced growth translates into higher productiveness (+1[ICON_PRODUCTION]/2 [ICON_CITIZEN]), and in the meantime it turns your city into cultural and religious capital (+2[ICON_CULTURE]; +1[ICON_PEACE]).');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_NEGATIVE_TEXT]Coast[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]River[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_MOHENJO_DARO_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_NEGATIVE_TEXT]Coast[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]River[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_MOHENJO_DARO_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
