-- Skara Brae
INSERT INTO Language_en_US 
			(Tag, Text)
VALUES		('TXT_KEY_BUILDING_SKARA_BRAE',			'Skara Brae'),
			('TXT_KEY_WONDER_SKARA_BRAE_QUOTE',		'[NEWLINE]"No great thing is created suddenly."[NEWLINE] - Epictetus[NEWLINE]'),
			('TXT_KEY_BUILDING_SKARA_BRAE_PEDIA',	'Skara Brae, located on the Orkney Islands of Scotland, is one of the best-preserved Neolithic settlements in Europe, often called the "Scottish Pompeii". Dating to around 3180–2500 BCE, it was uncovered in the mid-19th century after a powerful storm exposed the stone dwellings buried beneath sand dunes. The site provides remarkable insights into daily life in prehistoric times, revealing how early farming communities organized their homes, sustained themselves, and interacted with their environment. Its discovery transformed the understanding of Neolithic Britain, showing that people in this remote region lived in well-structured villages with surprising levels of comfort and sophistication. [NEWLINE][NEWLINE]The settlement consists of eight stone-built houses linked by covered passageways, each equipped with stone furniture such as beds, cupboards, hearths, and storage areas. The homes also featured drainage systems, suggesting a concern for cleanliness and efficient living. Artifacts found at the site—including tools, pottery, jewelry, and gaming pieces—reflect both domestic routines and aspects of social and cultural life. Skara Brae''s location near the coast eventually led to its abandonment, likely due to climate change or rising seas making the settlement less habitable. Today, as part of the UNESCO World Heritage Site "Heart of Neolithic Orkney", Skara Brae continues to captivate visitors as a vivid window into the lives of people more than 5,000 years ago.'),
			('TXT_KEY_BUILDING_SKARA_BRAE_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_SKARA_BRAE_HELP_CUT', '[COLOR_YIELD_FOOD]Skara Brae[ENDCOLOR] makes all of your basic resources much more efficient in terms of producing food (+1[ICON_FOOD]/[ICON_RES_COW][ICON_RES_COW], [ICON_RES_SHEEP][ICON_RES_SHEEP], [ICON_RES_FISH][ICON_RES_FISH], [ICON_RES_MAIZE][ICON_RES_MAIZE], [ICON_RES_RICE][ICON_RES_RICE], [ICON_RES_WHEAT][ICON_RES_WHEAT]). This means you will be able to sell more of your manufactred goods in all your [COLOR_CITY_BROWN]Villages[ENDCOLOR] when the middle ages arrive and you decide to built a few (+1[ICON_PRODUCTION], +1[ICON_GOLD]/[COLOR_CITY_BROWN]Tile in Empire[ENDCOLOR]; +1[ICON_PRODUCTION]).');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Coast[ENDCOLOR][NEWLINE][ICON_BULLET]Improved Resource: [ICON_RES_COW]/[ICON_RES_FISH]/[ICON_RES_SHEEP]/[ICON_RES_MAIZE]/ [ICON_RES_RICE]/[ICON_RES_WHEAT]'||Text WHERE Tag ='TXT_KEY_BUILDING_SKARA_BRAE_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Improved Resource: [ICON_RES_COW]/[ICON_RES_FISH]/[ICON_RES_SHEEP]/[ICON_RES_MAIZE]/ [ICON_RES_RICE]/[ICON_RES_WHEAT]'||Text WHERE Tag ='TXT_KEY_BUILDING_SKARA_BRAE_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
----------------------------------------------------
