-- Karnak
INSERT INTO Language_en_US 
			(Tag,								Text) 
VALUES		('TXT_KEY_BUILDING_KARNAK',			'Karnak'),
			('TXT_KEY_WONDER_KARNAK_QUOTE',		'[NEWLINE]"I was sitting in the Temple of Karnak of the Nile, as the sun was going down, and I was all alone, and the great Hypostyle Hall was full of shadows and ghosts of the past, (...) and if you believe that, you''ll believe anything."[NEWLINE] - Wilbur A. Smith[NEWLINE]'),
			('TXT_KEY_BUILDING_KARNAK_PEDIA',	'Karnak, located on the east bank of the Nile near Luxor in Egypt, is one of the largest and most impressive temple complexes ever constructed. Its history spans more than 1,500 years, with construction beginning during the Middle Kingdom (around 2000 BCE) and continuing through the Ptolemaic period (up to 30 BCE). Dedicated primarily to the Theban triad of Amun, Mut, and Khonsu, Karnak was not built all at once but expanded by successive pharaohs, each adding new temples, shrines, pylons, and monuments. As the chief religious center of ancient Egypt, it played a central role in political and spiritual life, hosting grand ceremonies, including the annual Opet Festival, which reinforced the divine authority of the pharaohs. [NEWLINE][NEWLINE]The complex covers over 100 hectares and contains a vast array of structures, the most famous of which is the Great Hypostyle Hall in the Temple of Amun. This hall, covering 5,000 square meters, contains 134 massive columns arranged in rows, some rising over 20 meters high, creating a forest of stone that still inspires awe today. Karnak also features sacred lakes, obelisks, colossal statues, and intricately carved reliefs that record military victories, offerings to the gods, and divine rituals. Its architectural scale and symbolic grandeur reflect the wealth and power of ancient Egypt at its height. Today, Karnak remains a UNESCO World Heritage Site and one of the most visited monuments in Egypt, offering a direct connection to the spiritual and political heart of ancient Egyptian civilization.'),
			('TXT_KEY_BUILDING_KARNAK_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_KARNAK_HELP_CUT', 'Temples of [COLOR_YIELD_FOOD]Karnak[ENDCOLOR] give you significant development advantage in many fields (+1[ICON_FOOD], +1[ICON_CULTURE], +1[ICON_PEACE]) and can turn rare [COLOR_CITY_GREEN]Oasis[ENDCOLOR] (+1[ICON_PRODUCTION], +1[ICON_PEACE]/[COLOR_CITY_GREEN]Tile[ENDCOLOR]) and [COLOR_CITY_GREEN]Flood Plains[ENDCOLOR] (+1[ICON_PRODUCTION], +1[ICON_PEACE]/2 [COLOR_CITY_GREEN]Tiles[ENDCOLOR]) into very productive sacred places. Remember, that recently constucted [COLOR_YIELD_FOOD]Monument[ENDCOLOR] ([COLOR_YIELD_FOOD]free[ENDCOLOR]; +1[ICON_CULTURE][ICON_CULTURE]), being the inherent part of the complex, should be the first of many, because now they generate even more culture than before.');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Flat[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Flood Plains[ENDCOLOR]/[COLOR_CYAN]Oasis[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_KARNAK_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Flood Plains[ENDCOLOR]/[COLOR_CYAN]Oasis[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_KARNAK_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
