-- Nazca Lines
INSERT INTO Language_en_US 
			(Tag,								Text) 
VALUES		('TXT_KEY_BUILDING_NAZCA',			'Nazca Lines'),
			('TXT_KEY_WONDER_NAZCA_QUOTE',		'[NEWLINE]"The true mystery of the world is the visible, not the invisible."[NEWLINE] - Oscar Wilde[NEWLINE]'),
			('TXT_KEY_BUILDING_NAZCA_PEDIA',	'The Nazca Lines, etched into the arid coastal plains of southern Peru, are one of the world''s most enigmatic archaeological wonders. Created by the Nazca culture between 500 BCE and 500 CE, these massive geoglyphs stretch across nearly 1,000 square kilometers of desert. The lines were formed by removing the reddish surface pebbles to reveal the lighter soil beneath, creating striking contrasts that have endured for centuries due to the region''s dry climate and lack of wind. First brought to international attention in the 1920s after being observed from the air, the Nazca Lines include straight paths, geometric figures, and vast depictions of animals, plants, and humanoid forms, ranging from simple designs to complex works spanning hundreds of meters. [NEWLINE][NEWLINE]The purpose of the geoglyphs remains a subject of debate among scholars. Some theories suggest they were astronomical calendars or ritual pathways connected to water and fertility ceremonies, while others argue they had religious significance, intended as offerings to deities seen from the sky. Among the most famous figures are the hummingbird, monkey, spider, and condor, all drawn with remarkable precision. Their scale and execution demonstrate both technical skill and a sophisticated cultural worldview. Today, the Nazca Lines are a UNESCO World Heritage Site, protected as a fragile testament to the creativity and spirituality of the ancient Nazca people, and they continue to fascinate researchers and visitors worldwide.'),
			('TXT_KEY_BUILDING_NAZCA_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_NAZCA_HELP_CUT', '[COLOR_YIELD_FOOD]Nazca Lines[ENDCOLOR] hide mysterious scientific secrets, that can be fully discovered only with air reconaissance ([COLOR_CYAN]Flight[ENDCOLOR]: +4[ICON_RESEARCH], +2[ICON_TOURISM]). Introducing new rituals on local [COLOR_CITY_BLUE]Plains[ENDCOLOR] (+2[ICON_FOOD]/[COLOR_CITY_BLUE]Tile[ENDCOLOR]) and [COLOR_CITY_BLUE]Hills[ENDCOLOR] (+1[ICON_PEACE]/[COLOR_CITY_BLUE]Tile[ENDCOLOR]) will surely change you into glorious religious leader, and constructing more [COLOR_CITY_BROWN]Camps[ENDCOLOR] will allow you to do researches in places, where others have no access into (+1[ICON_RESEARCH]/[COLOR_CITY_BROWN]Tile[ENDCOLOR]; +1[ICON_GREAT_SCIENTIST]).');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Plains[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_NEGATIVE_TEXT]Water[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_NAZCA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Plains[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_NAZCA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
