-- Wieliczka
INSERT INTO Language_en_US 
			(Tag,									Text) 
VALUES		('TXT_KEY_BUILDING_WIELICZKA',			'Wieliczka Salt Mine'),
			('TXT_KEY_WONDER_WIELICZKA_QUOTE',		'[NEWLINE]"You are the salt of the earth. But remember that salt is useful when in association, but useless in isolation."[NEWLINE] - Israelmore Ayivor[NEWLINE]'),
			('TXT_KEY_BUILDING_WIELICZKA_PEDIA',	'The Wieliczka Salt Mine, located near Kraków in southern Poland, is one of the oldest continuously operated salt mines in the world, with origins dating back to the 13th century. For centuries, it was a major source of wealth for the Polish crown, as salt was a highly prized commodity often referred to as "white gold." Mining activities continued for over 700 years until commercial operations ceased in 1996 due to flooding and declining profitability. Recognized as a UNESCO World Heritage Site in 1978, the mine stands as both a monument to Poland''s industrial history and a testament to the ingenuity of generations of miners who worked its depths. [NEWLINE][NEWLINE]Stretching over 300 kilometers of tunnels and reaching depths of more than 300 meters, the mine is renowned not only for its scale but also for its extraordinary underground artistry. Miners carved chapels, statues, reliefs, and even chandeliers entirely from salt, transforming the mine into a subterranean cultural treasure. The most famous site within is the Chapel of St. Kinga, a vast chamber adorned with salt-carved altars, biblical scenes, and intricate decorations that still hosts religious services and concerts. Today, the Wieliczka Salt Mine is one of Poland''s most popular tourist attractions, offering visitors a unique blend of natural geology, medieval engineering, and human creativity preserved underground.'),
			('TXT_KEY_BUILDING_WIELICZKA_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_WIELICZKA_HELP_CUT', '[COLOR_YIELD_FOOD]Wieliczka Salt Mine[ENDCOLOR] reveals hidden underground secret, greatly boosting your food generation (+5%[ICON_FOOD][ICON_FOOD]). Recently discovered rich deposits of [COLOR_GREY]Salt[ENDCOLOR] (2[ICON_RES_SALT] spawned; +1[ICON_PRODUCTION], +1[ICON_GOLD]/[ICON_RES_SALT]) will turn your underestimated [COLOR_CITY_BROWN]Mines[ENDCOLOR] into a strong pillar of your economy, substantially increasing the growth of your empire (+1[ICON_FOOD]/[COLOR_CITY_BROWN]Tile[ENDCOLOR]).');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Improvement: [COLOR_CYAN]2 Mines[ENDCOLOR][NEWLINE][ICON_BULLET]City: [COLOR_CYAN]place for [ICON_RES_SALT][ENDCOLOR][NEWLINE][ICON_BULLET]Map: [COLOR_CYAN][ICON_RES_SALT] on map[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_WIELICZKA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]City: [COLOR_CYAN]place for [ICON_RES_SALT][ENDCOLOR][NEWLINE][ICON_BULLET]Map: [COLOR_CYAN][ICON_RES_SALT] on map[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_WIELICZKA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
