-- Plain of Jars
INSERT INTO Language_en_US 
			(Tag,										Text) 
VALUES		('TXT_KEY_BUILDING_THONG_HAI_HIN',			'Plain of Jars'), /*Thong Hai Hin*/
			('TXT_KEY_WONDER_THONG_HAI_HIN_QUOTE',		'[NEWLINE]"As a well-spent day brings happy sleep, so life well used brings happy death."[NEWLINE] - Leonardo da Vinci[NEWLINE]'),
			('TXT_KEY_BUILDING_THONG_HAI_HIN_PEDIA',	'The Plain of Jars, located in the Xiangkhoang Plateau of northern Laos, is an enigmatic archaeological landscape dating from the Iron Age, roughly between 500 BCE and 500 CE. First documented by French explorers in the 1930s, the site consists of thousands of massive stone jars scattered across several plateaus. Their purpose remained a mystery for decades, but archaeological research suggests they were part of complex burial practices, possibly used to store human remains and associated grave goods before final interment. The Plain of Jars provides valuable insights into prehistoric societies in Southeast Asia and highlights their ritual and ceremonial sophistication. [NEWLINE][NEWLINE]The jars themselves vary in size, some exceeding three meters in height and weighing several tons, and are carved from sandstone, granite, or limestone. Many are arranged in clusters or circular patterns, sometimes accompanied by burial mounds and stone discs, indicating organized communal activity. The craftsmanship of the jars demonstrates advanced stone-carving skills and considerable effort to transport and position these massive objects across rugged terrain. Today, the Plain of Jars is a UNESCO World Heritage Site, although parts of it remain hazardous due to unexploded ordnance from the Laotian Civil War. Despite this, it continues to captivate researchers and visitors with its mysterious origins and monumental scale, offering a remarkable window into ancient Southeast Asian culture.'),
			('TXT_KEY_BUILDING_THONG_HAI_HIN_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_THONG_HAI_HIN_HELP_CUT', '[COLOR_YIELD_FOOD]Plain of Jars[ENDCOLOR] lays on the crossroad of multiple trade routes, so it must fulfill many different roles: a storehouse (Incoming Internal [ICON_INTERNATIONAL_TRADE]: +2[ICON_FOOD]), a cemetery (+3[ICON_PEACE]; 5[ICON_PEACE]/Death) or a market (+2[ICON_GOLD]; International [ICON_CARAVAN]: +2[ICON_GOLD]) making it an ideal spot for religious and economic center of your future empire.');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Flat[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Plains[ENDCOLOR], [COLOR_NEGATIVE_TEXT]Coast[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_THONG_HAI_HIN_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
