-- Malwiya Minaret
INSERT INTO Language_en_US 
			(Tag,									Text) 
VALUES		('TXT_KEY_BUILDING_MALWIYA',			'Malwiya Minaret'),
			('TXT_KEY_WONDER_MALWIYA_QUOTE',		'[NEWLINE]"Aim at heaven and you will get Earth... Aim at Earth and you will get neither."[NEWLINE] - C.S. Lewis[NEWLINE]'),
			('TXT_KEY_BUILDING_MALWIYA_PEDIA',		'The Malwiya Minaret, part of the Great Mosque of Samarra in Iraq, is an iconic architectural landmark built in the 9th century during the reign of the Abbasid Caliph Al-Mutawakkil (847–861 CE). The minaret was constructed as a component of one of the largest mosques in the world at the time, reflecting the Abbasid dynasty''s wealth, power, and architectural ambition. Its unique spiral design distinguishes it from traditional minarets, making it a symbol of Samarra and Islamic architecture. Over the centuries, the Malwiya Minaret has endured natural decay, invasions, and restoration efforts, yet it remains a testament to the innovative engineering and artistic vision of the early Islamic period. [NEWLINE][NEWLINE]The minaret rises approximately 52 meters high and features a distinctive spiral ramp that winds around the exterior, leading to a platform at the top from which the call to prayer would traditionally be made. Built from sandstone and baked brick, the Malwiya Minaret demonstrates both functional and aesthetic considerations, combining visibility across the flat landscape with an elegant, monumental form. The surrounding mosque, once among the largest in the Islamic world, is now in ruins, but the minaret itself continues to capture attention for its scale, design, and historical significance. Today, the Malwiya Minaret serves not only as a symbol of Samarra''s past glory but also as an enduring example of early Islamic architectural ingenuity.'),
			('TXT_KEY_BUILDING_MALWIYA_HELP',		'');
				
INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_MALWIYA_HELP_CUT', 'Construction of [COLOR_YIELD_FOOD]Malwiya Minaret[ENDCOLOR] is a result of engineering genious (+2[ICON_CULTURE]; +2[ICON_GREAT_ENGINEER]). Make sure to link your minerals with [COLOR_CITY_BROWN]Quarries[ENDCOLOR] (+1[ICON_PEACE]/[COLOR_CITY_BROWN]Tile in Empire[ENDCOLOR]; +1[ICON_PRODUCTION]), to use the power of your [COLOR_CITY_BROWN]Manufactories[ENDCOLOR] (+3[ICON_PEACE]/[COLOR_CITY_BROWN]Tile in Empire[ENDCOLOR]) and to rush your improved [COLOR_YIELD_FOOD]Stone Works[ENDCOLOR] as soon as possible (+2[ICON_PRODUCTION][ICON_PRODUCTION]).');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Flat[ENDCOLOR][NEWLINE][ICON_BULLET]Improvement: [COLOR_CYAN]Quarry[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_MALWIYA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Flat[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_MALWIYA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
