-- Buddhas of Bamiyan
INSERT INTO Language_en_US 
			(Tag,								Text)
VALUES		('TXT_KEY_BUILDING_BAMYAN',			'Buddhas of Bamiyan'),
			('TXT_KEY_WONDER_BAMYAN_QUOTE',		'[NEWLINE]"The past is already gone, the future is not yet here. There''s only one moment for you to live."[NEWLINE] - Buddha[NEWLINE]'),
			('TXT_KEY_BUILDING_BAMYAN_PEDIA',	'The Buddhas of Bamiyan, located in the Bamyan Valley of central Afghanistan, were monumental statues carved into the cliffs during the 6th century CE, representing an extraordinary fusion of Gandharan, Indian, and Hellenistic artistic influences. These colossal figures, measuring 55 and 38 meters in height, symbolized the spread of Mahayana Buddhism along the Silk Road, marking Bamiyan as a key religious and cultural center. The site bore witness to centuries of devotion, attracting pilgrims and traders alike. Tragically, in 2001, the statues were destroyed by the Taliban, an act that sparked global outrage and underscored the vulnerability of cultural heritage in conflict zones. [NEWLINE][NEWLINE]The Buddhas were carved directly into the sandstone cliffs, with details originally enhanced using stucco and pigments, giving them lifelike features and intricate ornamentation. Niches, caves, and smaller carvings surrounded the statues, serving as monastic and meditation spaces for Buddhist monks. The site''s monumental scale, combined with its remote and dramatic valley setting, made it both a spiritual landmark and a marvel of ancient engineering. Today, the empty niches remain as a poignant reminder of the past, and efforts are underway to preserve the site and reconstruct the memory of these iconic works, highlighting the enduring significance of the Bamiyan Buddhas in world heritage and Buddhist history.'),
			('TXT_KEY_BUILDING_BAMYAN_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_BAMYAN_HELP_CUT', 'Gigantic [COLOR_YIELD_FOOD]Buddhas of Bamiyan[ENDCOLOR] promote peace and generosity to the world (+2[ICON_PEACE]; +100%[ICON_RELIGION] Pressure). All your friends and allies, especially the smaller ones, will support your race to victory (+2[ICON_PEACE]/[ICON_CITY_STATE] Friend; +3[ICON_GOLDEN_AGE]/[ICON_CITY_STATE] Ally; +1[ICON_DIPLOMAT] League Vote/2 DoF). Protect this precious wonder, because many will try to destroy it (+2[ICON_CULTURE]; [COLOR_CYAN]Rocketry[ENDCOLOR]: +2[ICON_CULTURE], +2[ICON_GOLDEN_AGE]).');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]2 Mountains (range 3)[ENDCOLOR][NEWLINE][ICON_BULLET]Player: [COLOR_CYAN]at [ICON_PEACE] Peace[ENDCOLOR] (disabled after 33% [ICON_PRODUCTION] Progress)'||Text WHERE Tag ='TXT_KEY_BUILDING_BAMYAN_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = ''||Text WHERE Tag ='TXT_KEY_BUILDING_BAMYAN_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
