-- El Ghriba Synagogue (Holy)
INSERT INTO Language_en_US 
			(Tag,									Text) 
VALUES		('TXT_KEY_BUILDING_EL_GHRIBA',			'El Ghriba Synagogue'),
			('TXT_KEY_WONDER_EL_GHRIBA_QUOTE',		'[NEWLINE]"Jesus was born a Jew, and he died a Jew. It never occurred to him to establish a new religion. He never crossed himself - he had no reason to. He never set one foot in a church. He went to synagogue."[NEWLINE] - Amos Oz[NEWLINE]'),
			('TXT_KEY_BUILDING_EL_GHRIBA_PEDIA',	'El Ghriba Synagogue, located on the island of Djerba in Tunisia, is one of the oldest and most revered Jewish sites in North Africa, with origins traditionally traced back over 2,500 years. According to local legend, the synagogue was founded by Jews fleeing the destruction of the First Temple in Jerusalem, though historical records suggest it was built and expanded over centuries, particularly during the Roman and Byzantine periods. Serving as a spiritual and cultural center for the Jewish community of Djerba, El Ghriba has become a site of pilgrimage, especially during the annual Lag BaOmer festival, when thousands of visitors come to celebrate, pray, and honor the synagogue''s sacred history. [NEWLINE][NEWLINE]Architecturally, El Ghriba combines elements of local Berber and Mediterranean design, featuring whitewashed walls, ornate mosaics, and decorative ceramic tiles. The synagogue houses a revered stone, believed to have miraculous properties, which draws worshippers seeking blessings and protection. Inside, elaborately carved wooden doors, colorful chandeliers, and sacred Torah scrolls highlight the rich religious and artistic traditions of the Jewish community on Djerba. Despite challenges over the centuries, including attacks and periods of political instability, El Ghriba continues to function as both a living place of worship and a symbol of the enduring presence of Jewish heritage in Tunisia.'),
			('TXT_KEY_BUILDING_EL_GHRIBA_HELP',		''),
			('TXT_KEY_GREAT_WORK_THE_ARK',			'Ark of the Covenant'),
			('TXT_KEY_GREAT_WORK_THE_ARK_QUOTE',	'[NEWLINE]"I had it in my heart to build a house of rest [NEWLINE]for the ark of the covenant of the Lord, [NEWLINE]and for the footstool of our God."[NEWLINE] - 1 Chronicles, 28:2[NEWLINE]');
			
INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_EL_GHRIBA_HELP_CUT', '[COLOR_YIELD_FOOD]El Ghriba[ENDCOLOR] is a very unique [COLOR_YIELD_FOOD]Synagogue[ENDCOLOR] ([COLOR_YIELD_FOOD]free[ENDCOLOR]). It holds precious [COLOR_CULTURE_STORED]Ark of the Covenant[ENDCOLOR] (+1[ICON_CULTURE]; +4[ICON_PEACE]; +1[ICON_GW_ART]), which is a foundation stone of Judaism. History shows that Jews are masters of economy and can gain additional profits from unexpected sources (+1[ICON_GOLD]; 10%[ICON_PEACE] Faith Purchase into [ICON_GOLD]).');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_YIELD_PRODUCTION]Holy City[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_EL_GHRIBA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_YIELD_PRODUCTION]Holy City[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_EL_GHRIBA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
