-- Etchmiadzin Cathedral
INSERT INTO Language_en_US 
			(Tag,										Text) 
VALUES		('TXT_KEY_BUILDING_ETCHMIADZIN',			'Etchmiadzin Cathedral'),
			('TXT_KEY_WONDER_ETCHMIADZIN_QUOTE',		'[NEWLINE]"The wound of a dagger heals, but that of the tongue, never."[NEWLINE] - Armenian proverb[NEWLINE]'),
			('TXT_KEY_BUILDING_ETCHMIADZIN_PEDIA',		'Etchmiadzin Cathedral, located in the city of Vagharshapat in Armenia, is considered the spiritual and administrative center of the Armenian Apostolic Church and one of the oldest cathedrals in the world. Tradition holds that it was originally founded in 301 CE by Saint Gregory the Illuminator, following the adoption of Christianity as the state religion of Armenia—the first nation to do so. Over the centuries, the cathedral has undergone numerous renovations and expansions, reflecting various architectural styles, but it has remained the heart of Armenian Christian life. It has played a central role in shaping Armenian religious, cultural, and national identity, surviving invasions, earthquakes, and periods of political upheaval while maintaining its spiritual significance. [NEWLINE][NEWLINE]Architecturally, Etchmiadzin Cathedral features a cruciform design with a central dome and a combination of stone construction and decorative elements that reflect early Christian Armenian architecture. Inside, the cathedral houses sacred relics, manuscripts, and intricately carved altars, emphasizing its role as a religious and ceremonial center. The surrounding complex includes a seminary, museum, and monastic buildings, further underscoring its importance as a hub of theological study and pilgrimage. Recognized as a UNESCO World Heritage Site, Etchmiadzin Cathedral stands today not only as a place of worship but also as a testament to Armenia''s rich Christian heritage and its enduring cultural legacy.'),
			('TXT_KEY_BUILDING_ETCHMIADZIN_HELP',		''),
			('TXT_KEY_GREAT_WORK_HOLY_LANCE',			'Holy Lance'),
			('TXT_KEY_GREAT_WORK_HOLY_LANCE_QUOTE',		'[NEWLINE]One of the[NEWLINE]soldiers[NEWLINE]pierced his[NEWLINE]side with[NEWLINE]a lance, and[NEWLINE]immediately[NEWLINE]there came[NEWLINE]out blood[NEWLINE]and water.[NEWLINE] - John, 19:34[NEWLINE]');
			
INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_ETCHMIADZIN_HELP_CUT', '[COLOR_YIELD_FOOD]Etchmiadzin Cathedral[ENDCOLOR], which stores a magnificient peace of art, [COLOR_CULTURE_STORED]Holy Lance[ENDCOLOR] (+1[ICON_GW_ART]), may become your silent supporter in religious and cultural development (+2[ICON_PEACE]; +2[ICON_GOLDEN_AGE]; +1[ICON_PEACE]/[ICON_GREAT_WORK][ICON_GREAT_WORK]). Thanks to the efforts of high up religious nobles, your culture will bloom and golden ages will be even more frequent (10%[ICON_PEACE] into [ICON_CULTURE], [ICON_GOLDEN_AGE]).');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Grassland[ENDCOLOR], [COLOR_NEGATIVE_TEXT]Coast[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Forest[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_ETCHMIADZIN_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Forest[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_ETCHMIADZIN_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
