-- Sigiriya (Tradition, optional)
INSERT INTO Language_en_US 
			(Tag,										Text)
VALUES		('TXT_KEY_BUILDING_SIGIRIYA',				'Sigiriya'),
			('TXT_KEY_WONDER_SIGIRIYA_QUOTE',			'[NEWLINE]"I am Budal. Came with hundreds of people to see Sigiriya. Since all the others wrote poems, I did not!"[NEWLINE] - Text of the poem from 10th century[NEWLINE]'),
			('TXT_KEY_BUILDING_SIGIRIYA_PEDIA',			'Sigiriya, also known as Lion Rock, is an ancient rock fortress located in central Sri Lanka, dating back to the 5th century CE. It was built by King Kashyapa I (477–495 CE) as a royal citadel and palace complex, strategically perched atop a massive 200-meter-high granite rock. Sigiriya served both as a defensive stronghold and a symbol of royal power, combining military engineering with sophisticated urban planning. Rediscovered in the 19th century, the site revealed extensive gardens, reservoirs, frescoes, and inscriptions, showcasing the ingenuity of ancient Sri Lankan civilization. Today, Sigiriya is recognized as a UNESCO World Heritage Site and is considered one of the country''s most iconic archaeological landmarks. [NEWLINE][NEWLINE]The fortress complex includes elaborate water gardens, terraced gardens, and mirror-like pools, reflecting advanced hydraulic engineering and aesthetic sensibilities. The upper rock plateau houses the ruins of the royal palace, while the mid-level walls feature the famous frescoes of celestial maidens, admired for their vivid colors and delicate artistry. A massive stone gateway in the shape of a lion''s paws gives the site its name, "Lion Rock." Sigiriya demonstrates a remarkable blend of natural topography and human ingenuity, representing both a defensive citadel and a center of art, culture, and administration. Its preservation allows visitors to experience the grandeur and sophistication of ancient Sri Lankan architecture and landscape design.'),
			('TXT_KEY_BUILDING_SIGIRIYA_HELP',			''),
			('TXT_KEY_THEMING_BONUS_SIGIRIYA',			'Beautiful collection of native art'),
			('TXT_KEY_THEMING_BONUS_SIGIRIYA_HELP',		'To maximize your bonus, make sure all the Great Work Slots are all filled with art created by you.');
			
INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_SIGIRIYA_HELP_CUT', '[COLOR_YIELD_FOOD]Sigiriya[ENDCOLOR] on one side contains huge treasures hidden underground (200[ICON_GOLD]), and on the other hand stores many valuable artistic creations, that can be visible to all (+2[ICON_CULTURE]; +1[ICON_CULTURE]/[ICON_GREAT_WORK][ICON_GREAT_WORK]; 2[ICON_GW_ART], if themed: [ICON_GOLD], [ICON_CULTURE]), and all of them are safe on top of the unreachable hill (+3[ICON_STRENGTH]).');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Forest[ENDCOLOR]/[COLOR_CYAN]Jungle[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_SIGIRIYA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Forest[ENDCOLOR]/[COLOR_CYAN]Jungle[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_SIGIRIYA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	

UPDATE Language_en_US SET Text = REPLACE(Text, 'All requirements (including lua):', 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Tradition Finisher[ENDCOLOR]') WHERE Tag ='TXT_KEY_BUILDING_SIGIRIYA_HELP' AND EXISTS (SELECT * FROM Community WHERE Type='MW-SETTING-POLICIES' AND Value=1);
UPDATE Language_en_US SET Text = REPLACE(Text, 'Feature', 'Terrain: [COLOR_NEGATIVE_TEXT]Coast[ENDCOLOR][NEWLINE][ICON_BULLET]Feature') WHERE Tag ='TXT_KEY_BUILDING_SIGIRIYA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2) AND EXISTS (SELECT * FROM Community WHERE Type='MW-SETTING-POLICIES' AND Value=0);

UPDATE Language_en_US SET Text = '[NEWLINE]----------------[NEWLINE]'||Text WHERE Tag ='TXT_KEY_BUILDING_SIGIRIYA_HELP';
UPDATE Language_en_US SET Text = 'Possible Theming Bonuses:[NEWLINE][ICON_BULLET]+7 [ICON_CULTURE] and [ICON_TOURISM] for two [COLOR_POSITIVE_TEXT]Domestic[ENDCOLOR] [ICON_GW_ART]'||Text WHERE Tag ='TXT_KEY_BUILDING_SIGIRIYA_HELP';
