-- Chand Baori
INSERT INTO Language_en_US 
			(Tag,									Text) 
VALUES		('TXT_KEY_BUILDING_CHAND_BAORI',		'Chand Baori'),
			('TXT_KEY_WONDER_CHAND_BAORI_QUOTE',	'[NEWLINE]"When the well''s dry, we know the worth of water."[NEWLINE] - Benjamin Franklin[NEWLINE]'),
			('TXT_KEY_BUILDING_CHAND_BAORI_PEDIA',	'Chand Baori, located in the village of Abhaneri in Rajasthan, India, is one of the largest and most elaborate stepwells in the world, built during the 8th–9th centuries CE by King Chanda of the Nikumbh dynasty. Stepwells were constructed across arid regions of India to provide reliable access to water throughout the year, serving both practical and social purposes. Chand Baori, in particular, was designed to supply water to the local population, livestock, and agricultural lands while also functioning as a cool retreat during the scorching desert summers. Its construction reflects the ingenuity and engineering expertise of ancient Indian architects in adapting to harsh environmental conditions. [NEWLINE][NEWLINE]The stepwell descends approximately 30 meters deep and consists of 3,500 narrow steps arranged in a geometric pattern across 13 levels, forming a visually striking inverted pyramid. The walls are adorned with intricate carvings depicting gods, dancers, and floral motifs, combining utility with artistic expression. At the bottom lies a water reservoir, which remains functional during the dry season. Chand Baori is not only an engineering marvel but also a cultural symbol, reflecting the social, religious, and architectural traditions of medieval Rajasthan. Today, it attracts tourists and scholars alike, serving as a testament to India''s rich heritage of water management and monumental design.'),
			('TXT_KEY_BUILDING_CHAND_BAORI_HELP',	'');

INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_CHAND_BAORI_HELP_CUT', '[COLOR_YIELD_FOOD]Chand Baori[ENDCOLOR] guarantees, that your local [COLOR_CITY_BLUE]Desert[ENDCOLOR] will not be a barren wasteland (+1[ICON_FOOD]/[COLOR_CITY_BLUE]Tile[ENDCOLOR]; +2[ICON_FOOD]). It is also a place, where new specialists settle their offices (+1[ICON_GOLD]; -3[ICON_HAPPINESS_3] Urbanization) and very important and profitable deals between nobles are agreed (+2[ICON_CULTURE]; [COLOR_YIELD_GOLD]free [ICON_GREAT_PEOPLE][ENDCOLOR]; +10%[ICON_GREAT_PEOPLE]).');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Desert[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_NEGATIVE_TEXT]Fresh Water[ENDCOLOR][NEWLINE][ICON_BULLET]Building: [COLOR_CYAN]Well[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_CHAND_BAORI_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Feature: [COLOR_NEGATIVE_TEXT]Fresh Water[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_CHAND_BAORI_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
