-- Prophet's Mosque
INSERT INTO Language_en_US 
			(Tag,									Text)
VALUES		('TXT_KEY_BUILDING_NABAWI',				'Prophet''s Mosque'),
			('TXT_KEY_WONDER_NABAWI_QUOTE',			'[NEWLINE]"When you see a person who has been given more than you in money and beauty, look to those, who have been given less."[NEWLINE] - Prophet Muhammad[NEWLINE]'),
			('TXT_KEY_BUILDING_NABAWI_PEDIA',		'Al-Masjid al-Nabawi, also known as the Prophet''s Mosque, is located in the city of Medina, Saudi Arabia, and is the second holiest site in Islam after the Masjid al-Haram in Mecca. Originally built by the Prophet Muhammad in 622 CE shortly after his migration (Hijra) from Mecca, it served as a community center, court, and religious school, as well as a place of worship. Over the centuries, the mosque has undergone numerous expansions under various Islamic rulers, including the Umayyads, Abbasids, and the modern Saudi state, transforming it into one of the largest and most architecturally significant mosques in the world. The mosque also houses the Prophet Muhammad''s tomb, making it a central pilgrimage site for Muslims worldwide. [NEWLINE][NEWLINE]The mosque complex today covers hundreds of thousands of square meters and features striking green and white minarets, vast prayer halls, and retractable umbrellas in the courtyard that provide shade for worshippers. Its interior is adorned with intricate Islamic calligraphy, mosaics, and marble flooring, reflecting both spiritual significance and architectural grandeur. The mosque also includes the Rawdah, a revered area between the Prophet''s tomb and his pulpit, considered one of the gardens of Paradise according to Islamic tradition. Al-Masjid al-Nabawi continues to be a focal point of Muslim devotion, scholarship, and community life, symbolizing the enduring spiritual and cultural legacy of Islam.'),
			('TXT_KEY_BUILDING_NABAWI_HELP',		''),
			('TXT_KEY_THEMING_BONUS_NABAWI',		'Islamic calligraphy works'),
			('TXT_KEY_THEMING_BONUS_NABAWI_HELP',	'To maximize your bonus, make sure both Great Works are filled with Writings created by you.');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_NABAWI_HELP_CUT', '[COLOR_YIELD_FOOD]Prophet''s Mosque[ENDCOLOR] is one of the biggests [COLOR_YIELD_FOOD]Mosques[ENDCOLOR] of the world ([COLOR_YIELD_FOOD]free[ENDCOLOR]). Built by Prophet Muhammad, it is historically important religious centre (+5[ICON_PEACE]; +10%[ICON_PEACE][ICON_PEACE]) where you can learn arabic religious literature (+20%[ICON_GREAT_WRITER]; 2[ICON_GW_WRITING], if themed: [ICON_PEACE], [ICON_GOLDEN_AGE]). Remodeled by multiple cultures, it is still the most beautiful and astonishing temple you can see (+2[ICON_CULTURE]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_YIELD_PRODUCTION]Holy City[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_NABAWI_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);		
