-- Moray
INSERT INTO Language_en_US 
			(Tag,									Text)
VALUES		('TXT_KEY_BUILDING_MORAY',				'Moray'),
			('TXT_KEY_WONDER_MORAY_QUOTE',			'[NEWLINE]"Science is a way of thinking much more than it is a body of knowledge."[NEWLINE] - Carl Sagan[NEWLINE]'),
			('TXT_KEY_BUILDING_MORAY_PEDIA',		'The Moray Terraces, located in the Sacred Valley of Peru near Cusco, are an extraordinary example of Inca agricultural ingenuity, dating back to the 15th century. Believed to have been an experimental agricultural laboratory, the site consists of a series of concentric terraces carved into a natural depression, allowing the Incas to study the effects of different climatic conditions on crops. Each level of terrace created a distinct microclimate, with temperature differences of up to 15 °C between the top and bottom, enabling the cultivation of a wide variety of crops such as maize, potatoes, and quinoa. The site demonstrates the Incas'' advanced understanding of agronomy, irrigation, and soil conservation, highlighting their ability to adapt agriculture to diverse environmental conditions. [NEWLINE][NEWLINE]The terraces themselves are constructed with retaining stone walls, sophisticated drainage systems, and channels that prevent erosion while maximizing water distribution. The circular design not only optimized sunlight exposure and temperature control but also minimized the risk of frost damage, illustrating a highly strategic approach to farming in the Andean highlands. Beyond its agricultural function, Moray likely held ritual and ceremonial significance, reflecting the Inca belief in the sacredness of land and crops. Today, the Moray Terraces are a popular archaeological site, offering insight into the technological, cultural, and spiritual sophistication of the Inca civilization.'),
			('TXT_KEY_BUILDING_MORAY_HELP',			'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_MORAY_HELP_CUT', '[COLOR_YIELD_FOOD]Moray[ENDCOLOR], mysterious agricultural structures constructed on [COLOR_CITY_BLUE]Hills[ENDCOLOR] (+1[ICON_FOOD], +1[ICON_PRODUCTION], +1[ICON_RESEARCH]/[COLOR_CITY_BLUE]Tile[ENDCOLOR]; +2[ICON_FOOD]; +5%[ICON_FOOD][ICON_FOOD]) allow you to grow unusual plants and crops in places, where they are not naturally seen (+2[ICON_RESEARCH]). Use your scientific advantage to boost your growth even more (15%[ICON_RESEARCH] into [ICON_FOOD]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_NEGATIVE_TEXT]Coast[ENDCOLOR][NEWLINE][ICON_BULLET]Improvement: [COLOR_CYAN]Farm[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_MORAY_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_NEGATIVE_TEXT]Coast[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_MORAY_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	

UPDATE Language_en_US SET Text = REPLACE(Text, 'All requirements (including lua):', 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Progress Finisher[ENDCOLOR]') WHERE Tag ='TXT_KEY_BUILDING_MORAY_HELP' AND EXISTS (SELECT * FROM Community WHERE Type='MW-SETTING-POLICIES' AND Value=1);
