-- Lavaux
INSERT INTO Language_en_US 
			(Tag,									Text)
VALUES		('TXT_KEY_BUILDING_LAVAUX',				'Lavaux'),
			('TXT_KEY_WONDER_LAVAUX_QUOTE',			'[NEWLINE]"A bottle of wine contains more philosophy than all the books in the world."[NEWLINE] - Louis Pasteur[NEWLINE]'),
			('TXT_KEY_BUILDING_LAVAUX_PEDIA',		'Lavaux, located along the northern shores of Lake Geneva in Switzerland, is a historic wine-growing region with origins dating back to the 11th century. Monks from nearby Benedictine and Cistercian monasteries began cultivating vineyards on the steep, terraced slopes, shaping the landscape to optimize sunlight exposure and drainage for grape production. Over centuries, the region developed a unique viticultural tradition, producing high-quality wines that contributed to local culture and economy. Lavaux''s combination of human ingenuity and natural beauty reflects a harmonious interaction between people and the environment, earning it UNESCO World Heritage status in 2007. [NEWLINE][NEWLINE]The terraces of Lavaux are supported by dry-stone walls, which prevent soil erosion and create microclimates ideal for cultivating grape varieties such as Chasselas. The landscape is punctuated by historic villages, wine cellars, and pathways that allow visitors to explore the vineyards while enjoying panoramic views of Lake Geneva and the Alps. The region''s design not only maximizes agricultural productivity but also preserves centuries of cultural and architectural heritage. Today, Lavaux remains a vibrant center of wine production and tourism, offering a living example of sustainable land use and the enduring legacy of traditional viticulture in Switzerland.'),
			('TXT_KEY_BUILDING_LAVAUX_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_LAVAUX_HELP_CUT', 'Wineyards of [COLOR_YIELD_FOOD]Lavaux[ENDCOLOR] are well-known source of unique grapes (2[ICON_RES_WINE] spawned; +1[ICON_FOOD], +1[ICON_GOLD], +1[ICON_PEACE]/[ICON_RES_WINE]). Try to make all your citizens much happier (-10%[ICON_HAPPINESS_3][ICON_HAPPINESS_3] Needs; +1[ICON_GOLD]) working these tasty fruits grown in crystal clear waters of nearby [COLOR_CITY_GREEN]Lake[ENDCOLOR] (+1[ICON_FOOD]/[COLOR_CITY_GREEN]Tile[ENDCOLOR]; +2[ICON_FOOD]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Lake[ENDCOLOR][NEWLINE][ICON_BULLET]City: [COLOR_CYAN]place for [ICON_RES_WINE][ENDCOLOR][NEWLINE][ICON_BULLET]Map: [COLOR_CYAN][ICON_RES_WINE] on map[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_LAVAUX_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Lake[ENDCOLOR][NEWLINE][ICON_BULLET]City: [COLOR_CYAN]place for [ICON_RES_WINE][ENDCOLOR][NEWLINE][ICON_BULLET]Map: [COLOR_CYAN][ICON_RES_WINE] on map[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_LAVAUX_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
