-- Wartburg
INSERT INTO Language_en_US 
			(Tag,										Text)
VALUES		('TXT_KEY_BUILDING_WARTBURG',				'Wartburg'),
			('TXT_KEY_WONDER_WARTBURG_QUOTE',			'[NEWLINE]"In nature we never see anything isolated, but everything in connection with something else which is before it, beside it, under it and over it."[NEWLINE] - Johann Wolfgang von Goethe[NEWLINE]'),
			('TXT_KEY_BUILDING_WARTBURG_PEDIA',			'The Wartburg Castle, perched on a hill overlooking the town of Eisenach in Thuringia, Germany, was originally built around 1067 by Ludwig der Springer. Over the centuries, it became one of the most significant medieval fortresses in Germany, serving as a residence for nobility and a center of cultural and political activity. Its historical prominence is particularly linked to Martin Luther, who, in 1521–1522, took refuge at Wartburg after being declared an outlaw by the Holy Roman Empire. During his stay, Luther translated the New Testament from Greek into German, an act that had a profound impact on religion, literacy, and culture in Europe. Wartburg has been recognized for its historical, architectural, and cultural significance and is now a UNESCO World Heritage Site. [NEWLINE][NEWLINE]Architecturally, Wartburg Castle exhibits a blend of Romanesque, Gothic, and later Renaissance styles, reflecting centuries of construction and renovation. The castle includes fortified walls, towers, and a keep, as well as elegant halls, chapels, and residential quarters adorned with frescoes and period furnishings. Its strategic hilltop location provided both defense and commanding views of the surrounding landscape. Today, Wartburg is a museum and tourist attraction, offering visitors insights into medieval life, Reformation history, and the artistic heritage of Germany, while standing as a symbol of cultural resilience and historical memory.'),
			('TXT_KEY_BUILDING_WARTBURG_HELP',			''),
			('TXT_KEY_THEMING_BONUS_WARTBURG',			'Literature that inspired whole nations'),
			('TXT_KEY_THEMING_BONUS_WARTBURG_HELP',		'To maximize your bonus, make sure all the Great Work Slots are all filled with literature created by you.');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_WARTBURG_HELP_CUT', 'With [COLOR_YIELD_FOOD]Wartburg[ENDCOLOR] you will become the king of literature (+1[ICON_CULTURE]; +2[ICON_GREAT_WRITER]; +30%[ICON_GREAT_WRITER]), which can be stored in an overwhelming library (+1[ICON_GOLDEN_AGE]; 3[ICON_GW_WRITING], if themed: [ICON_CULTURE], [ICON_PEACE], [ICON_GOLDEN_AGE]) located in a castle (+4[ICON_STRENGTH]). All [COLOR_YIELD_FOOD]Writer''s Guilds[ENDCOLOR] will be inspired by the cutting-edge religious ideas (+1[ICON_PEACE][ICON_PEACE]), and your generals will be able to use this collection to develop new training methods (+5 XP/[COLOR_YIELD_GOLD]Land[ENDCOLOR]/[ICON_GREAT_WORK] inside).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Progress Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Forest[ENDCOLOR][NEWLINE][ICON_BULLET]Building: [COLOR_CYAN]Writer''s Guild[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_WARTBURG_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Progress Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Building: [COLOR_CYAN]Writer''s Guild[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_WARTBURG_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	

UPDATE Language_en_US SET Text = '[NEWLINE]----------------[NEWLINE]'||Text WHERE Tag ='TXT_KEY_BUILDING_WARTBURG_HELP';
UPDATE Language_en_US SET Text = 'Possible Theming Bonuses:[NEWLINE][ICON_BULLET]+15 [ICON_CULTURE] and [ICON_TOURISM] for three [COLOR_POSITIVE_TEXT]Domestic[ENDCOLOR] [ICON_GW_WRITING]'||Text WHERE Tag ='TXT_KEY_BUILDING_WARTBURG_HELP';
