-- Ahu Tongariki
INSERT INTO Language_en_US 
			(Tag,								Text) 
VALUES		('TXT_KEY_BUILDING_AHU',			'Ahu Tongariki'),
			('TXT_KEY_WONDER_AHU_QUOTE',		'[NEWLINE]"The metaphor is so obvious. Easter Island isolated in the Pacific Ocean - once the island got into trouble, there was no way they could get free. There was no other people from whom they could get help. In the same way that we on planet Earth, if we ruin our own world, we won''t be able to get help."[NEWLINE] - Jared Diamond[NEWLINE]'),
			('TXT_KEY_BUILDING_AHU_PEDIA',		'Ahu Tongariki, located on Easter Island (Rapa Nui) in the southeastern Pacific Ocean, is the largest ceremonial platform (ahu) on the island, famous for its impressive row of 15 moai statues. The site dates back to the 13th–15th centuries CE and was originally constructed by the Rapa Nui people as a tribute to important ancestors and as a center for religious and social gatherings. Like other moai sites on the island, Ahu Tongariki reflects the islanders'' sophisticated understanding of stone carving, transportation, and ritual practice. The platform and its statues were destroyed during internal conflicts in the 18th–19th centuries but were restored in 1995 after being toppled by a tsunami, making the site both a historical and cultural emblem of Rapa Nui resilience. [NEWLINE][NEWLINE]The moai at Ahu Tongariki stand on a massive stone platform, each carved from volcanic tuff and ranging from 4 to 10 meters in height. The statues feature elongated faces, prominent noses, and stylized torsos, and many originally bore pukao—cylindrical stone hats made from red scoria. The arrangement of the moai facing inland signifies their role as watchful ancestors protecting the communities. Today, Ahu Tongariki is not only a major tourist attraction but also an important site for archaeological study, providing insights into Rapa Nui society, spirituality, and the islanders'' remarkable achievements in engineering and artistry.'),
			('TXT_KEY_BUILDING_AHU_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_AHU_HELP_CUT', 'Monumental platform, [COLOR_YIELD_FOOD]Ahu Tongariki[ENDCOLOR], significantly boosts your production of nearby [COLOR_CITY_BROWN]Quarries[ENDCOLOR] (+2[ICON_PRODUCTION]/[COLOR_CITY_BROWN]Tile[ENDCOLOR]) and expands your culture with every [COLOR_GREY]Stone[ENDCOLOR] deposit (+1[ICON_CULTURE]/[ICON_RES_STONE][ICON_RES_STONE]). Vision of the greater future motivates workers to finish this magnificient project (+20%[ICON_WORKER]), and what''s more, local resource, the [COLOR_GREY]Tern Egg[ENDCOLOR], is a God''s sign of good will announcing long-lasting prosperity (+1[ICON_RES_TERN]; +5%[ICON_PEACE][ICON_PEACE]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Coast[ENDCOLOR][NEWLINE][ICON_BULLET]Improved Resource: [ICON_RES_STONE]'||Text WHERE Tag ='TXT_KEY_BUILDING_AHU_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Coast[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_AHU_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
