-- Falun Mine
INSERT INTO Language_en_US 
			(Tag,								Text) 
VALUES		('TXT_KEY_BUILDING_FALUN',			'Falun Mine'),
			('TXT_KEY_WONDER_FALUN_QUOTE',		'[NEWLINE]"Mining is like a search-and-destroy mission."[NEWLINE] - Stewart Udall[NEWLINE]'),
			('TXT_KEY_BUILDING_FALUN_PEDIA',	'The Falun Mine, located in Dalarna County, Sweden, was one of the most important copper mines in Europe and played a central role in Sweden''s economy and industrial development for over a millennium. Mining at the site began as early as the 10th century, but the mine reached its peak between the 17th and 18th centuries, supplying much of Europe with copper, which was essential for coinage, artillery, and various industrial applications. The wealth generated by the Falun Mine contributed significantly to the rise of the Swedish Empire, making it a strategic economic and political asset. Operations continued in various capacities until 1992, after which mining ceased, leaving behind a historical and industrial legacy preserved for posterity. [NEWLINE][NEWLINE]The Falun Mine complex includes massive open-pit workings, underground tunnels, and extensive surface buildings such as smelting facilities, worker housing, and administrative structures. Its distinctive red tailings, known as the Great Pit, dominate the landscape and are a visible reminder of centuries of extraction. The site also features well-preserved miners'' cottages, chapels, and industrial infrastructure that illustrate the social and technological history of mining life. Today, the Falun Mine is a UNESCO World Heritage Site, recognized for its historical, technological, and cultural significance, attracting visitors interested in industrial heritage, engineering, and the history of mining in Europe.'),
			('TXT_KEY_BUILDING_FALUN_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_FALUN_HELP_CUT', '[COLOR_CITY_BROWN]Mining[ENDCOLOR] complex at [COLOR_YIELD_FOOD]Falun[ENDCOLOR] makes all crucial investments possible (+1[ICON_GOLD]/[COLOR_CITY_BROWN]Tile[ENDCOLOR]; +1[ICON_GOLD]). Quick surge of engineering staff (2%[ICON_GREAT_ENGINEER] progress/[COLOR_YIELD_FOOD]Medieval (or later) Building[ENDCOLOR] construction) and militaristic experts (+1[ICON_GREAT_GENERAL]; [COLOR_YIELD_GOLD]free [ICON_GREAT_GENERAL][ENDCOLOR]) guarantees successes on many fronts. Recently discovered [COLOR_GREY]Copper[ENDCOLOR] deposits (2[ICON_RES_COPPER] spawned; +1[ICON_GOLD], +1[ICON_GOLDEN_AGE]/[ICON_RES_COPPER]) can easily buy you the leadership of the world.';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Improvement: [COLOR_CYAN]2 Mines[ENDCOLOR][NEWLINE][ICON_BULLET]City: [COLOR_CYAN]place for [ICON_RES_COPPER][ENDCOLOR][NEWLINE][ICON_BULLET]Map: [COLOR_CYAN][ICON_RES_COPPER] on map[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_FALUN_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]City: [COLOR_CYAN]place for [ICON_RES_COPPER][ENDCOLOR][NEWLINE][ICON_BULLET]Map: [COLOR_CYAN][ICON_RES_COPPER] on map[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_FALUN_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
----------------------------------------------------
-- Forge of Damascus
INSERT INTO Language_en_US 
			(Tag,									Text) 
VALUES		('TXT_KEY_BUILDING_DAMASCUS',			'Forge of Damascus'),
			('TXT_KEY_WONDER_DAMASCUS_QUOTE',		'[NEWLINE]"The reputation and history of Damascus steel has given rise to many legends, such as the ability to cut through a rifle barrel or to cut a hair falling across the blade. The manufacturing technique has yet to be reverse engineered, even in modern times."[NEWLINE] - From legends about Damascus Steel[NEWLINE]'),
			('TXT_KEY_BUILDING_DAMASCUS_PEDIA',		'The term "Forge of Damascus" refers to the renowned steel production and blade-forging workshops historically located in Damascus, Syria. These forges were famed for producing Damascus steel, a high-carbon steel known for its distinctive wavy patterns and exceptional strength. The steel was crafted using the wootz process, which originated in South India and involved melting iron in a crucible with carbon-rich materials. The resulting ingots were then traded across the Middle East, including to Damascus, where skilled artisans forged them into weapons such as swords and knives. These blades gained legendary status for their sharpness, resilience, and the unique patterns on their surfaces. [NEWLINE][NEWLINE]The exact methods used in the original Damascus steel production have been lost over time, but modern metallurgical studies suggest that the distinctive patterns were due to the presence of carbon nanotubes and nanowires in the steel. Today, the term "Damascus steel" is often used to describe pattern-welded steel, where layers of different metals are forged together to create similar aesthetic patterns. While the ancient Damascus forges no longer operate, the legacy of their craftsmanship continues to influence modern blacksmithing and blade-making techniques.'),
			('TXT_KEY_BUILDING_DAMASCUS_HELP',		''),
			('TXT_KEY_PROMOTION_DAMASCUS',			'Damascus Steel'),
			('TXT_KEY_PROMOTION_DAMASCUS_HELP',		'+10%[ICON_STRENGTH]CS.');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_DAMASCUS_HELP_CUT', '[COLOR_YIELD_FOOD]Forge of Damascus[ENDCOLOR] holds a secret forging technology turning melee weaponry into a masterpiece ([COLOR_WATER_TEXT]Damascus Steel[ENDCOLOR]/[COLOR_YIELD_GOLD]Melee Land[ENDCOLOR]; [COLOR_CYAN]Metallurgy[ENDCOLOR]: +3[ICON_PRODUCTION]). Your production and science literally explodes (+2[ICON_PRODUCTION]; +3[ICON_RESEARCH]; +2[ICON_GREAT_SCIENTIST]), so remember to claim all available [COLOR_GREY]Iron[ENDCOLOR] deposits to gain an advantage over your enemies (+1[ICON_PRODUCTION], +1[ICON_RESEARCH]/[ICON_RES_IRON][ICON_RES_IRON]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Authority Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Fresh Water[ENDCOLOR][NEWLINE][ICON_BULLET]Improved Resource: [ICON_RES_IRON]'||Text WHERE Tag ='TXT_KEY_BUILDING_DAMASCUS_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Authority Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Improved Resource: [ICON_RES_IRON]'||Text WHERE Tag ='TXT_KEY_BUILDING_DAMASCUS_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
