-- Shwedagon Pagoda
INSERT INTO Language_en_US 
			(Tag,												Text)
VALUES		('TXT_KEY_BUILDING_SHWEDAGON',						'Shwedagon Pagoda'),
			('TXT_KEY_WONDER_SHWEDAGON_QUOTE',					'[NEWLINE]"There was a tumult among men and spirits, the blind beheld objects, the deaf heard sounds. The earth quaked, lightning flashed, gems rained down until they were knee deep, and all trees of the Himalayas, though not in season, bore blossoms and fruit."[NEWLINE] - King Okkalapa[NEWLINE]'),
			('TXT_KEY_BUILDING_SHWEDAGON_PEDIA',				'Shwedagon Paya (also known as Shwedagon Pagoda or the Great Dragon Pagoda), located in Yangon, Myanmar, is one of the most sacred Buddhist sites in the country and a symbol of Burmese religious devotion. Its origins are believed to date back over 2,500 years, making it one of the oldest pagodas in the world, though the exact founding date is uncertain. According to legend, the pagoda enshrines relics of four previous Buddhas, including eight strands of hair from Gautama Buddha, making it a central pilgrimage site for Buddhists. Over the centuries, Shwedagon Pagoda has undergone multiple restorations and expansions, particularly under the patronage of Burmese kings, and it has survived invasions, earthquakes, and colonial periods, maintaining its spiritual and cultural significance. [NEWLINE][NEWLINE]Architecturally, Shwedagon Pagoda is renowned for its stunning gilded stupa, which rises approximately 99 meters high and is adorned with thousands of gold plates and encrusted with diamonds, rubies, and other precious stones. The complex includes numerous smaller temples, shrines, bells, and statues, all arranged around the central stupa, with intricately decorated terraces and courtyards for worshippers. Its golden exterior reflects sunlight during the day and glows spectacularly at night, creating a striking visual presence. Today, Shwedagon Pagoda remains an active center of worship, meditation, and cultural gatherings, attracting both local devotees and international visitors while symbolizing Myanmar''s enduring Buddhist heritage.'),
			('TXT_KEY_BUILDING_SHWEDAGON_HELP',					''),
			('TXT_KEY_THEMING_BONUS_SHWEDAGON_KALPA',			'Relics of the four previous Buddhas of the present kalpa'),
			('TXT_KEY_THEMING_BONUS_SHWEDAGON_CONSECUTIVE',		'Relics from most recent eras'),
			('TXT_KEY_THEMING_BONUS_SHWEDAGON_PLAYERS',			'Relics from different creators'),
			('TXT_KEY_THEMING_BONUS_SHWEDAGON_ARTIFACTS',		'Bunch of Relics'),
			('TXT_KEY_THEMING_BONUS_SHWEDAGON_HELP',			'To maximize your bonus, make sure all the Great Work Slots are all filled with Artifacts created by different Players in consecutive Eras.'),
			('TXT_KEY_PROMOTION_HIDDEN_ARTIFACTS',				'Diplomatic Passport'),
			('TXT_KEY_PROMOTION_HIDDEN_ARTIFACTS_HELP',			'+20% [ICON_WORKER] Work Rate. Unit [COLOR:255:230:85:255]can Enter (cannot Dig on) Enemy Territory without Open Borders Agreement[ENDCOLOR].');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_SHWEDAGON_HELP_CUT', '[COLOR_YIELD_FOOD]Shwedagon Pagoda[ENDCOLOR] fully focuses on every aspect related to artistry (+2[ICON_CULTURE]; +2[ICON_GREAT_ARTIST]; +2[ICON_PEACE]/[ICON_ARTIST][ICON_ARTIST]) increasing the overall value of your collection (+2[ICON_GOLD]; +1[ICON_GOLD]/[ICON_GREAT_WORK][ICON_GREAT_WORK]). You can now organize brilliant vernissages, where you will be able to present recent discoveries (4[ICON_GW_ART], if themed: [ICON_GOLD], [ICON_CULTURE], [ICON_PEACE], [ICON_TOURISM]). Make also sure to use your new abilities to find hidden artifacts ([COLOR_WATER_TEXT]Diplomatic Passport[ENDCOLOR]/[COLOR_YIELD_GOLD]Archaeologist[ENDCOLOR]). Let your city shine!';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Tradition Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Fresh Water[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_SHWEDAGON_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Tradition Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Fresh Water[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_SHWEDAGON_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	

UPDATE Language_en_US SET Text = '[NEWLINE]----------------[NEWLINE]'||Text WHERE Tag ='TXT_KEY_BUILDING_SHWEDAGON_HELP';
UPDATE Language_en_US SET Text = 'Possible Theming Bonuses:[NEWLINE][ICON_BULLET]+20 [ICON_CULTURE] and [ICON_TOURISM] for four [ICON_ARTIFACT][NEWLINE][ICON_BULLET]+24 [ICON_CULTURE] and [ICON_TOURISM] for four [ICON_ARTIFACT] from [COLOR_POSITIVE_TEXT]different Civilizations[ENDCOLOR][NEWLINE][ICON_BULLET]+32 [ICON_CULTURE] and [ICON_TOURISM] for four [ICON_ARTIFACT] from [COLOR_CYAN]consecutive Eras[ENDCOLOR][NEWLINE][ICON_BULLET]+40 [ICON_CULTURE] and [ICON_TOURISM] for four [ICON_ARTIFACT] from [COLOR_POSITIVE_TEXT]different Civilizations[ENDCOLOR] and [COLOR_CYAN]consecutive Eras[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_SHWEDAGON_HELP';
