-- Mont-Saint-Michel
INSERT INTO Language_en_US 
			(Tag,								Text) 
VALUES		('TXT_KEY_BUILDING_MICHEL',			'Mont-Saint-Michel'),
			('TXT_KEY_WONDER_MICHEL_QUOTE',		'[NEWLINE]"Church and State, Soul and Body, God and Man, are all one at Mont-Saint-Michel, and the business of all is to fight, each in his own way, or to stand guard for each other."[NEWLINE] - Henry Adams[NEWLINE]'),
			('TXT_KEY_BUILDING_MICHEL_PEDIA',	'Mont Saint-Michel, located off the coast of Normandy in France, is a historic island commune renowned for its medieval architecture and strategic significance. Its origins date back to the 8th century when Aubert, the Bishop of Avranches, is said to have built a small church on the rocky island following a vision of the Archangel Michael. Over the centuries, the site evolved into a fortified abbey and monastic complex, becoming both a center of pilgrimage and a stronghold during periods of conflict, including the Hundred Years'' War. Mont Saint-Michel''s unique location—rising dramatically from tidal waters—enhanced its defensive capabilities while establishing it as a symbol of spiritual and cultural resilience. [NEWLINE][NEWLINE]Architecturally, Mont Saint-Michel combines Romanesque and Gothic styles, with the abbey perched at the summit and surrounded by defensive walls and narrow, winding streets leading down to the village. The abbey features impressive vaulted ceilings, cloisters, and chapels, showcasing the ingenuity of medieval builders in adapting to the island''s steep, rocky terrain. The surrounding village includes stone houses, shops, and ramparts that evoke a medieval atmosphere. Today, Mont Saint-Michel is a UNESCO World Heritage Site and a major tourist attraction, celebrated not only for its striking architecture and historical significance but also for its breathtaking natural setting, where tides can dramatically alter the landscape around the island.'),
			('TXT_KEY_BUILDING_MICHEL_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_MICHEL_HELP_CUT', 'Lonely [COLOR_YIELD_FOOD]Mont-Saint-Michel[ENDCOLOR] will turn your vulnerable city into a fortress (+6[ICON_STRENGTH]; +50 HP), where you can focus on your soul and dream about the future (+4[ICON_PEACE]/5 [ICON_CITIZEN]; +1[ICON_GOLDEN_AGE]). Unique conditions allow you to breed an original kind of [COLOR_GREY]Sheep[ENDCOLOR] (1[ICON_RES_SHEEP] spawned; +1[ICON_FOOD], +1[ICON_GOLD]/[ICON_RES_SHEEP][ICON_RES_SHEEP]; +1[ICON_FOOD]), especially when you discover advanced technologies predicitng the tides (+1[ICON_GOLD]; [COLOR_CYAN]Computers[ENDCOLOR]: +1[ICON_PRODUCTION], +3[ICON_GOLD], +5[ICON_TOURISM]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: one of the two: [COLOR_CYAN]Single-tile Island (2 tiles away from a mainland)[ENDCOLOR] or [COLOR_CYAN]Tile surrounded by 5 tiles of water connected to a Mainland[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_MICHEL_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);		
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Single-tile Island[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_MICHEL_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);		
----------------------------------------------------
-- Buyuk Han
INSERT INTO Language_en_US 
			(Tag,									Text) 
VALUES		('TXT_KEY_BUILDING_BUYUK_HAN',			'Büyük Han'),
			('TXT_KEY_WONDER_BUYUK_HAN_QUOTE',		'[NEWLINE]"There is no friendship in trade."[NEWLINE] - Cornelius Vanderbilt[NEWLINE]'),
			('TXT_KEY_BUILDING_BUYUK_HAN_PEDIA',	'Büyük Han, located in Nicosia, Cyprus, is one of the finest examples of Ottoman-era caravanserais on the island, built in 1572 shortly after the Ottoman conquest of Cyprus. It functioned as an inn for traders and travelers, providing lodging, stables, and storage facilities in a secure, communal environment. Over the centuries, Büyük Han also served various roles, including a prison during British colonial rule in the 19th century, reflecting the shifting political and social history of Cyprus. Its enduring presence offers a glimpse into the island''s Ottoman past and its role as a crossroads of commerce and culture in the eastern Mediterranean. [NEWLINE][NEWLINE]Architecturally, Büyük Han features a rectangular plan with a central open courtyard surrounded by two floors of vaulted rooms and arcaded galleries. The ground floor housed shops and stables, while the upper floor contained guest rooms accessed by stone staircases. The inner courtyard includes a mosque and a small fountain, providing a communal and spiritual focal point. The structure''s thick stone walls, pointed arches, and decorative elements illustrate the functional yet elegant Ottoman architectural style. Today, Büyük Han has been restored and repurposed as a cultural center, housing artisan shops, cafés, and galleries, making it a vibrant hub for both locals and visitors while preserving its historical and architectural significance.'),
			('TXT_KEY_BUILDING_BUYUK_HAN_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_BUYUK_HAN_HELP_CUT', '[COLOR_YIELD_FOOD]Büyük Han[ENDCOLOR], a beautiful [COLOR_YIELD_FOOD]Caravansary[ENDCOLOR] ([COLOR_YIELD_FOOD]free[ENDCOLOR]), provides wide trading opportunities and place for contemplation (+1[ICON_FOOD]; +1[ICON_PEACE]). You can now hire brand new [COLOR_YIELD_GOLD]free Caravan[ENDCOLOR], use new tools to improve craftsmanship in your [COLOR_CITY_BROWN]Villages[ENDCOLOR] (+2[ICON_PRODUCTION]/[COLOR_CITY_BROWN]Tile in Empire[ENDCOLOR]; +1[ICON_PRODUCTION]) or find new trading partners (+2[ICON_GOLD]; [COLOR_CYAN]Corporations[ENDCOLOR]: +2[ICON_PRODUCTION], +3[ICON_GOLD]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Progress Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Flat[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Coast[ENDCOLOR][NEWLINE][ICON_BULLET]Improvement: [COLOR_CYAN]Village[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_BUYUK_HAN_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);		
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Progress Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Flat[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Coast[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_BUYUK_HAN_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);		
