-- Ait Benhaddou
INSERT INTO Language_en_US 
			(Tag,									Text) 
VALUES		('TXT_KEY_BUILDING_BENHADDOU',			'Ait Benhaddou'), /*Aït Benhaddou*/
			('TXT_KEY_WONDER_BENHADDOU_QUOTE',		'[NEWLINE]"Are you not entertained?"[NEWLINE] - Maximus Decimus Meridius[NEWLINE]'),
			('TXT_KEY_BUILDING_BENHADDOU_PEDIA',	'Ait Benhaddou, located in the foothills of the High Atlas Mountains in Morocco, is a historic ksar (fortified village) that dates back to at least the 17th century, though some sources suggest origins even earlier. It was an important stop along the trans-Saharan trade routes, serving as a hub for merchants traveling between Marrakech and the desert regions to the south. The village is a prime example of the earthen clay architecture typical of southern Morocco and reflects the social and economic organization of pre-Saharan communities. Over centuries, Ait Benhaddou became both a residential settlement and a protective fortress, guarding its inhabitants and caravans against raids. [NEWLINE][NEWLINE]Architecturally, Ait Benhaddou is built from mud bricks, rammed earth, and stone, forming a compact cluster of houses, granaries, and defensive walls with corner towers. Narrow alleyways and communal spaces wind through the ksar, leading to a hilltop citadel that provides both defense and oversight of the surrounding landscape. The uniform reddish-brown hue of the buildings blends harmoniously with the arid environment, creating a striking visual effect. Today, Ait Benhaddou is a UNESCO World Heritage Site and a popular destination for tourists and filmmakers, celebrated not only for its architectural beauty but also as a living example of Morocco''s cultural and historical heritage. As well as an exhibit of Moroccan architecture, Aït Benhaddou has also been featured in several films; including ''Jesus of Nazareth'', ''the Mummy'', ''Gladiator'' and ''Prince of Persia''.'),
			('TXT_KEY_BUILDING_BENHADDOU_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_BENHADDOU_HELP_CUT', 'Huge [COLOR_YIELD_FOOD]Ait Benhaddou[ENDCOLOR] [COLOR_CITY_BROWN]Village[ENDCOLOR] is a fantastic tourist attraction (+3[ICON_GOLD], +3[ICON_TOURISM]/[COLOR_CITY_BROWN]Tile[ENDCOLOR]) and proved to be an ideal scenography for numerous movie projects (+2[ICON_CULTURE]; [COLOR_CYAN]Radio[ENDCOLOR]: +4[ICON_TOURISM]). This harsh settlement relies heavily on nearby [COLOR_CITY_GREEN]River[ENDCOLOR] (+1[ICON_FOOD]/[COLOR_CITY_GREEN]Tile[ENDCOLOR]; +2[ICON_FOOD]) and expands your current trade network onto the unreachable desert sands (+2[ICON_GOLD]; +1[ICON_INTERNATIONAL_TRADE]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Desert[ENDCOLOR][NEWLINE][ICON_BULLET]Improvement: [COLOR_CYAN]Village[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_BENHADDOU_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Desert[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_BENHADDOU_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
