-- Kilwa Kisiwani
INSERT INTO Language_en_US 
			(Tag,										Text) 
VALUES		('TXT_KEY_BUILDING_KILWA_KISIWANI',			'Kilwa Kisiwani'),
			('TXT_KEY_WONDER_KILWA_KISIWANI_QUOTE',		'[NEWLINE]"Kilwa is one of the most beautifully built cities in the world. The houses there are entirely made of wood, their rooftops out of rope grass, and it rains with great vigour."[NEWLINE] - Ibn Battuta[NEWLINE]'),
			('TXT_KEY_BUILDING_KILWA_KISIWANI_PEDIA',	'Kilwa Kisiwani, located off the southern coast of present-day Tanzania, was one of the most important city-states of the Swahili Coast, flourishing between the 9th and 16th centuries CE. Established by Persian and Arab traders, Kilwa became a major hub for maritime trade, connecting East Africa with Arabia, India, and China. The city''s wealth was derived from the export of gold, ivory, and other African commodities, and it played a key role in spreading Islam along the East African coast. European explorers and Portuguese forces later arrived in the 16th century, leading to the city''s gradual decline, though its ruins remain a powerful testament to its historical significance in regional trade and cultural exchange. [NEWLINE][NEWLINE]The archaeological remains of Kilwa Kisiwani include mosques, palaces, coral stone houses, and fortifications, illustrating the city''s sophistication and urban planning. The Great Mosque of Kilwa, one of the earliest and largest in East Africa, and the Husuni Kubwa palace highlight advanced architectural techniques, including the use of coral rag and intricate stone carving. The city''s layout, with streets, marketplaces, and residential areas, reflects its role as a thriving commercial and religious center. Today, Kilwa Kisiwani is a UNESCO World Heritage Site, recognized for its historical, cultural, and architectural value, providing insight into the Swahili civilization and its connections across the Indian Ocean world.'),
			('TXT_KEY_BUILDING_KILWA_KISIWANI_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_KILWA_KISIWANI_HELP_CUT', '[COLOR_YIELD_FOOD]Kilwa Kisiwani[ENDCOLOR] trade hub (+2[ICON_INTERNATIONAL_TRADE]) acquires for you additional copies of rare luxuries (+1 [ICON_RES_JEWELRY]; +1 [ICON_RES_PORCELAIN]). Coordination of this huge project gives you quick profits (+2[ICON_GOLD]) and allows you to find new trade areas increasing the value of potentially useless spare local resources (+1[ICON_PRODUCTION]/all [COLOR_GREY]Strategic Resources[ENDCOLOR]; +1[ICON_GOLD]/all [COLOR_GREY]Luxury Resources[ENDCOLOR]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Statecraft Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Coast[ENDCOLOR][NEWLINE][ICON_BULLET]Improvement: [COLOR_CYAN]2 (Mines + Camps)[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_KILWA_KISIWANI_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Statecraft Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Coast[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_KILWA_KISIWANI_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
