-- Golden Pavilion
INSERT INTO Language_en_US 
			(Tag,									Text) 
VALUES		('TXT_KEY_BUILDING_KINKAKU_JI',			'Golden Pavilion'), /*Rokuon-ji, Kinkaku-ji*/
			('TXT_KEY_WONDER_KINKAKU_JI_QUOTE',		'[NEWLINE]"A book holds a house of gold."[NEWLINE] - Chinese proverb[NEWLINE]'),
			('TXT_KEY_BUILDING_KINKAKU_JI_PEDIA',	'Kinkaku-ji, also known as the Golden Pavilion, is a Zen Buddhist temple located in Kyoto, Japan, with origins dating back to 1397. Originally built as a retirement villa for the shogun Ashikaga Yoshimitsu, it was later converted into a temple according to his will. Kinkaku-ji has a storied history, having been burned down several times over the centuries, most notably in 1950, before being reconstructed in 1955. The temple is renowned not only for its religious significance but also for its cultural and aesthetic importance, representing the Muromachi period''s ideals of harmony, elegance, and connection with nature. It has been recognized as a UNESCO World Heritage Site and is one of Japan''s most visited and photographed landmarks. [NEWLINE][NEWLINE]Architecturally, Kinkaku-ji is a three-story pavilion set beside a tranquil pond, with the top two floors covered entirely in gold leaf, reflecting beautifully in the surrounding water. Each floor is designed in a distinct style: the first in the Shinden style of the aristocracy, the second in the Bukke style of samurai residences, and the third in the Chinese Zen Hall style. The temple is surrounded by meticulously maintained gardens that integrate natural landscapes with human design, emphasizing a sense of balance and serenity. Today, Kinkaku-ji continues to serve as a symbol of Kyoto''s cultural heritage, attracting visitors from around the world who come to admire its stunning beauty and historical significance.'),
			('TXT_KEY_BUILDING_KINKAKU_JI_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_KINKAKU_JI_HELP_CUT', 'Breathtaking [COLOR_YIELD_FOOD]Golden Pavilion[ENDCOLOR] has strong bond with nature: clear and azure [COLOR_CITY_GREEN]Lakes[ENDCOLOR] (+1[ICON_FOOD], +1[ICON_CULTURE], +2[ICON_PEACE]/[COLOR_CITY_GREEN]Tile in Empire[ENDCOLOR]), wild and impenetrable [COLOR_CITY_GREEN]Forests[ENDCOLOR] and [COLOR_CITY_GREEN]Jungles[ENDCOLOR] (+1[ICON_CULTURE], +1[ICON_PEACE]/[COLOR_CITY_GREEN]Tile[ENDCOLOR]), and wide meandering [COLOR_CITY_GREEN]Rivers[ENDCOLOR] as well (+1[ICON_FOOD]/[COLOR_CITY_GREEN]Tile[ENDCOLOR]). These beautiful gardens create a peaceful and inspiring aura for many writers (+2[ICON_CULTURE]; 1[ICON_GW_WRITING]) spending their leisure time there, and also looking for some answers (+3[ICON_PEACE]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Fealty Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Fresh Water[ENDCOLOR], [COLOR_CYAN]Forest[ENDCOLOR]/[COLOR_CYAN]Jungle[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_KINKAKU_JI_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);		
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Fealty Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Fresh Water[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_KINKAKU_JI_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);		
