-- Harmandir Sahib (Holy)
INSERT INTO Language_en_US 
			(Tag,									Text) 
VALUES		('TXT_KEY_BUILDING_HARMANDIR',			'Harmandir Sahib'),
			('TXT_KEY_WONDER_HARMANDIR_QUOTE',		'[NEWLINE]"The Giver of peace is eternally blissful."[NEWLINE] - Sri Guru Granth Sahib[NEWLINE]'),
			('TXT_KEY_BUILDING_HARMANDIR_PEDIA',	'Harmandir Sahib, also known as the Golden Temple, is the holiest shrine of Sikhism, located in Amritsar, Punjab, India. It was founded in 1581 by Guru Ram Das, the fourth Sikh Guru, and completed by his successor, Guru Arjan Dev, in 1604. The temple was built as a place of spiritual worship open to all, regardless of caste or religion. Guru Arjan Dev installed the Guru Granth Sahib, the central holy scripture of Sikhism, inside the temple, making it the spiritual and cultural heart of the Sikh faith. Over centuries, the temple endured attacks and was rebuilt multiple times, including its gold-plated renovation under Maharaja Ranjit Singh in the early 19th century, which gave it its iconic appearance. [NEWLINE][NEWLINE]The Golden Temple is a stunning architectural masterpiece, blending Hindu and Islamic styles with a distinctive Sikh identity. Surrounded by the Amrit Sarovar (Pool of Nectar), the temple''s shimmering gold-covered façade and marble inlays create a breathtaking spectacle. It has four entrances, symbolizing openness and inclusivity, and a causeway leading to the sanctum, where continuous recitation of the Guru Granth Sahib takes place. The temple complex also houses the Akal Takht, the highest seat of Sikh religious authority, and the world''s largest free community kitchen (Langar), serving meals to thousands daily. Harmandir Sahib remains a symbol of Sikh devotion, resilience, and universal brotherhood.'),
			('TXT_KEY_BUILDING_HARMANDIR_HELP',		'');

INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_HARMANDIR_HELP_CUT', 'Four open doors to [COLOR_YIELD_FOOD]Harmandir Sahib[ENDCOLOR] welcome everyone, no matter what race they are or religion they follow (-2[ICON_HAPPINESS_3][ICON_HAPPINESS_3] Religious Unrest). Each visitor will be well fed (+2[ICON_FOOD]/all [COLOR_YIELD_FOOD]Buildings yielding [ICON_PEACE][ENDCOLOR]) and treated properly if wounded (10 HP Heal/[COLOR_YIELD_GOLD]Land Garrison[ENDCOLOR]). Sikhs'' religion is a peaceful faith (+2[ICON_PEACE]), so please, visit this astonishing [COLOR_YIELD_FOOD]Gurdwara[ENDCOLOR], to convert yourself, and maybe even change someone else''s point of view.');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_YIELD_PRODUCTION]Holy City[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_HARMANDIR_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_YIELD_PRODUCTION]Holy City[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_HARMANDIR_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
