-- Old Bridge
INSERT INTO Language_en_US 
			(Tag,									Text) 
VALUES		('TXT_KEY_BUILDING_OLD_BRIDGE',			'Old Bridge'),
			('TXT_KEY_WONDER_OLD_BRIDGE_QUOTE',		'[NEWLINE]"A refugee is someone who survived and who can create the future."[NEWLINE] - Amela Koluder[NEWLINE]'),
			('TXT_KEY_BUILDING_OLD_BRIDGE_PEDIA',	'The Old Bridge (Stari Most) in Mostar, Bosnia and Herzegovina, is a historic Ottoman-era bridge originally built in the 16th century under the direction of the Ottoman architect Mimar Hayruddin. Completed in 1566 during the reign of Sultan Suleiman the Magnificent, the bridge was designed to connect the two parts of Mostar across the Neretva River, facilitating trade and communication while symbolizing the city''s cultural and economic significance. For centuries, Stari Most stood as a testament to Ottoman engineering and the coexistence of diverse communities in the region. Tragically, it was destroyed in 1993 during the Bosnian War, but its reconstruction, completed in 2004 using original techniques and materials, restored both its physical presence and symbolic role as a bridge between cultures. [NEWLINE][NEWLINE]Architecturally, the Old Bridge is an elegant single-span stone arch, measuring approximately 29 meters in height and 28 meters in length, supported by precisely cut limestone blocks. Its graceful curve and simple yet robust design demonstrate advanced engineering for its time, while the surrounding Ottoman-era structures, including fortified towers on each bank, complement its historic setting. The bridge has become a symbol of reconciliation, resilience, and cultural heritage, attracting visitors worldwide. Today, Stari Most is a UNESCO World Heritage Site, celebrated not only for its architectural beauty but also for its enduring representation of unity and peace in a region with a complex history.'),
			('TXT_KEY_BUILDING_OLD_BRIDGE_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_OLD_BRIDGE_HELP_CUT', '[COLOR_YIELD_FOOD]Old Bridge[ENDCOLOR] is your scream announcing to the world leaders the will of bringing peace for the good of all people involved in numerous conflicts (+2[ICON_DIPLOMAT] League Votes; +1[ICON_HAPPINESS_1]). Use your diplomatic strength and all known tricks to bring hesitating nations onto your side ([COLOR_YIELD_GOLD]free [ICON_DIPLOMAT][ENDCOLOR]; +2[ICON_DIPLOMAT]). This bridge is not only a symbol or a wonderful architectural creation, but also a spot worth visiting for meditation (+1[ICON_CULTURE])';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Statecraft Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]River[ENDCOLOR][NEWLINE][ICON_BULLET]Player: [COLOR_CYAN]at [ICON_PEACE] Peace[ENDCOLOR] (disabled after 33% [ICON_PRODUCTION] Progress)'||Text WHERE Tag ='TXT_KEY_BUILDING_OLD_BRIDGE_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);		
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Statecraft Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]River[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_OLD_BRIDGE_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);		
