-- Meenakshi Temple
INSERT INTO Language_en_US 
			(Tag,									Text) 
VALUES		('TXT_KEY_BUILDING_MEENAKSHI',			'Meenakshi Temple'),
			('TXT_KEY_WONDER_MEENAKSHI_QUOTE',		'[NEWLINE]"We greet you, Devi Meenakshi, she who shines like a thousand-million suns, adorned with bracelets and garlands... She who is auspicious, she who embodies existence. I always bow to you, whose compassion is an ocean."[NEWLINE] - Adi Shankara[NEWLINE]'),
			('TXT_KEY_BUILDING_MEENAKSHI_PEDIA',	'Meenakshi Temple, located in the city of Madurai in Tamil Nadu, India, is one of the most important and historically significant Hindu temples in South India. Its origins date back over 2,500 years, with substantial expansions occurring during the reign of the Nayak dynasty in the 16th and 17th centuries. The temple is dedicated to Goddess Meenakshi, an incarnation of Parvati, and her consort Lord Sundareswarar, a form of Shiva. Serving as both a religious center and a cultural hub, the temple has been a focal point for rituals, festivals, and pilgrimages, reflecting the rich spiritual and artistic traditions of Tamil Nadu. Its historical significance is also tied to the city of Madurai itself, which developed around the temple as a major center of politics, commerce, and learning. [NEWLINE][NEWLINE]Architecturally, Meenakshi Temple is renowned for its towering gopurams (gateway towers) adorned with thousands of colorful sculptures depicting gods, goddesses, mythical creatures, and scenes from Hindu epics. The temple complex spans over 14 acres, featuring pillared halls, sacred tanks, and intricately carved mandapams (pavilions) used for ceremonies and cultural performances. The Thousand-Pillared Hall, a highlight of the temple, showcases exquisite stone carvings and serves as a testament to the craftsmanship of the Nayak period. Today, Meenakshi Temple continues to be a vibrant religious and cultural landmark, attracting millions of devotees and tourists, and standing as a symbol of South Indian temple architecture and heritage.'),
			('TXT_KEY_BUILDING_MEENAKSHI_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_MEENAKSHI_HELP_CUT', 'Colorful [COLOR_YIELD_FOOD]Meenakshi Temple[ENDCOLOR] amazes anyone who will decide to visit it (+2[ICON_CULTURE]; +1[ICON_PEACE]/6 [ICON_CITIZEN][ICON_CITIZEN]). Central [COLOR_YIELD_FOOD]Mandir[ENDCOLOR] ([COLOR_YIELD_FOOD]free[ENDCOLOR]) contains numerous wonderful artistic creations (+1[ICON_FOOD]/[ICON_GREAT_WORK][ICON_GREAT_WORK]) praising Goddess Parwati, whose great support ensures fertility of nearby [COLOR_CITY_GREEN]Lakes[ENDCOLOR] and [COLOR_CITY_GREEN]Rivers[ENDCOLOR] (+1[ICON_PEACE]/[COLOR_CITY_GREEN]Tile[ENDCOLOR]; +1[ICON_FOOD]) and spiritual transformation of your soul. Change yourself to save the world (5%[ICON_PEACE] Faith Purchase into [ICON_FOOD]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_YIELD_PRODUCTION]Holy City[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_MEENAKSHI_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);		
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_YIELD_PRODUCTION]Holy City[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_MEENAKSHI_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);		
