-- Peterhof Palace
INSERT INTO Language_en_US 
			(Tag,									Text) 
VALUES		('TXT_KEY_BUILDING_PETERHOF',			'Peterhof Palace'),
			('TXT_KEY_WONDER_PETERHOF_QUOTE',		'[NEWLINE]"It is my great desire to reform my subjects, and yet I am ashamed to confess that I am unable to reform myself."[NEWLINE] - Peter The Great[NEWLINE]'),
			('TXT_KEY_BUILDING_PETERHOF_PEDIA',		'Peterhof Palace, located on the southern coast of the Gulf of Finland near St. Petersburg, Russia, is a grand palace complex often referred to as the "Russian Versailles". It was commissioned by Peter the Great in the early 18th century as a symbol of Russia''s emergence as a European power and as a showcase of imperial grandeur. Built to rival the palaces of Western Europe, Peterhof served as a summer residence for the Russian tsars and a venue for state ceremonies, celebrations, and diplomatic receptions. Over time, the complex was expanded by successive rulers, incorporating elaborate gardens, fountains, and pavilions, reflecting both political ambition and the influence of Baroque architecture and landscaping. [NEWLINE][NEWLINE]Peterhof is renowned for its extensive gardens and remarkable water features, which include the Grand Cascade, a series of terraces, fountains, and gilded statues that lead down from the palace to the Gulf of Finland. The Lower Gardens feature geometrically arranged parterres, smaller fountains, and grottoes, while the Upper Gardens provide a more formal, symmetrical layout. The Grand Palace itself is adorned with ornate interiors, gilded decorations, and elaborate halls designed to impress visitors. Today, Peterhof is a UNESCO World Heritage Site and a major tourist destination, celebrated for its architectural brilliance, artistic achievements, and the ingenuity of its hydraulic engineering that allows its fountains to operate without pumps.'),
			('TXT_KEY_BUILDING_PETERHOF_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_PETERHOF_HELP_CUT', 'Your recent projects brought a fortune to your court, and [COLOR_YIELD_FOOD]Peterhof Palace[ENDCOLOR] is a reflection of all these events (+7[ICON_GOLDEN_AGE]; 20[ICON_HAPPINESS_1] WLTKD turns). Beautiful interiors and outstanding gardens filled with myriad of fountains attract to your palace many majestic nobles (+10%[ICON_GREAT_PEOPLE]), and the splendour around you additionally motivates your citizens to even harder work for the common good (+15%[ICON_PRODUCTION], +15%[ICON_GOLD], +25%[ICON_GOLDEN_AGE] during [ICON_HAPPINESS_1] WLTKD).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Flat[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Coast[ENDCOLOR][NEWLINE][ICON_BULLET]Improved Resource [ICON_RES_IRON]'||Text WHERE Tag ='TXT_KEY_BUILDING_PETERHOF_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);		
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Coast[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_PETERHOF_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);		
