-- Bakken
INSERT INTO Language_en_US 
			(Tag,								Text) 
VALUES		('TXT_KEY_BUILDING_BAKKEN',			'Bakken'),
			('TXT_KEY_WONDER_BAKKEN_QUOTE',		'[NEWLINE]"Amusement is appealing because we don''t have to think. It spares us the fear and anxiety that might otherwise prey on our thoughts."[NEWLINE] - John Ortberg[NEWLINE]'),
			('TXT_KEY_BUILDING_BAKKEN_PEDIA',	'Bakken, located near Klampenborg just north of Copenhagen, Denmark, is the world''s oldest operating amusement park, with origins dating back to 1583. It began as a natural spring known for its supposed healing properties, attracting visitors from across the region. Over time, entertainment and leisure activities, including performances, games, and rides, developed around the spring, gradually evolving into a formal amusement park. Bakken has played a central role in Danish culture for centuries, serving as a popular destination for locals and tourists seeking recreation, social gatherings, and festive events. [NEWLINE][NEWLINE]The park features a mix of traditional and modern attractions, combining historic wooden roller coasters and carousels with contemporary rides, games, and entertainment venues. Its charming, forested setting contributes to a unique atmosphere, blending nature with leisure. In addition to rides, Bakken hosts live performances, seasonal festivals, and dining establishments, reflecting a long tradition of social and cultural activity. Today, Bakken continues to attract visitors from around the world, offering a living example of centuries-old amusement traditions while maintaining its historic charm and appeal.'),
			('TXT_KEY_BUILDING_BAKKEN_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_BAKKEN_HELP_CUT', '[COLOR_YIELD_FOOD]Bakken[ENDCOLOR] amusement park provides entertainment on maximum level for both: the masses and the nobles (+3[ICON_HAPPINESS_1]), greatly increasing your tourist traffic (+3[ICON_TOURISM]; +33%[ICON_TOURISM]/[ICON_HAPPINESS_1] WLTKD) and profits it can generate at its peak (+2[ICON_GOLD]). Wide variety of attarctions (+1[ICON_CULTURE]) guarantees that the festival will be long and satisfying (10[ICON_HAPPINESS_1] WLTKD turns).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Player: [COLOR_CYAN]Happiness > 70%[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_BAKKEN_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);		
UPDATE Language_en_US SET Text = ''||Text WHERE Tag ='TXT_KEY_BUILDING_BAKKEN_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);		
