-- House of Trades of the Indies
INSERT INTO Language_en_US 
			(Tag,										Text) 
VALUES		('TXT_KEY_BUILDING_HOUSE_OF_TRADE',			'House of Trade of the Indies'),
			('TXT_KEY_WONDER_HOUSE_OF_TRADE_QUOTE',		'[NEWLINE]"All other lands found on the western side of the boundary shall belong to the King and Queen of Castille - and their successors."[NEWLINE] - From the "Treaty of Tordesillas"[NEWLINE]'),
			('TXT_KEY_BUILDING_HOUSE_OF_TRADE_PEDIA',	'The Real Audiencia y Casa de la Contratación de Indias, or simply Casa de Contratación (House of Trade), was established in 1503 by the Spanish Crown in Seville to regulate and oversee all aspects of trade, navigation, and colonial affairs between Spain and its territories in the Americas. Initially, it functioned as a central agency responsible for managing the purchase, transport, warehousing, and sale of merchandise exported to and imported from Spain''s newly discovered American territories. As Spanish exploration and colonization expanded, the Casa''s commercial and financial responsibilities grew, encompassing the licensing of voyages, training of navigators, creation of maps and charts, and the administration of estates of Spaniards dying overseas. [NEWLINE][NEWLINE]Architecturally, the Casa de Contratación was initially located in the Real Alcázar of Seville, occupying the Cuarto del Almirante and other rooms within the palace complex. This setting provided proximity to the port of Seville, facilitating the management of maritime activities. In 1717, the institution was transferred to Cádiz due to the silting of the Guadalquivir River, which had made Seville''s port less navigable. The Casa de Contratación continued its operations until 1790, when it was abolished as part of a broader reorganization of colonial administration. Today, the legacy of the Casa de Contratación is preserved in the Archivo General de Indias in Seville, which houses extensive records documenting Spain''s colonial history'),
			('TXT_KEY_BUILDING_HOUSE_OF_TRADE_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_HOUSE_OF_TRADE_HELP_CUT', 'In times of dynamic development and unrestrained expansion [COLOR_YIELD_FOOD]House of Trade[ENDCOLOR] bonds your strong military with trade so tightly, that it feels natural (+10%[ICON_PRODUCTION]/[COLOR_YIELD_GOLD]Military Naval[ENDCOLOR], [COLOR_YIELD_GOLD]Cargo[ENDCOLOR]). Military protection is needed in such a difficult situation ([COLOR_YIELD_GOLD]free [ICON_GREAT_ADMIRAL][ENDCOLOR]; +1[ICON_GREAT_ADMIRAL]), especially when you have to expand farther away to find new extraordinary markets (+2[ICON_INTERNATIONAL_TRADE]) and substantially raise your income to survive (+3[ICON_GOLD]; +2[ICON_GREAT_MERCHANT]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Coast[ENDCOLOR][NEWLINE][ICON_BULLET]Player: [COLOR_CYAN]2 [ICON_CITY_STATE] City-State Allies[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_HOUSE_OF_TRADE_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Coast[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_HOUSE_OF_TRADE_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
