-- Solovietsky Monastery
INSERT INTO Language_en_US 
			(Tag,										Text) 
VALUES		('TXT_KEY_BUILDING_SOLOVIETSKY',			'Solovietsky Monastery'),
			('TXT_KEY_WONDER_SOLOVIETSKY_QUOTE',		'[NEWLINE]"Everything is defeated before love."[NEWLINE] - Elder Thaddeus of Vitovnica[NEWLINE]'),
			('TXT_KEY_BUILDING_SOLOVIETSKY_PEDIA',		'Solovetsky Monastery, located on the Solovetsky Islands in the White Sea of northern Russia, was founded in 1436 by the monk Zosima, with earlier monastic activity initiated by Herman and Savvatiy in 1429. The monastery rapidly expanded, becoming a significant religious, cultural, and economic center in the Russian North. By the 17th century, it had grown into a fortified complex with a substantial community of monks and laypeople, engaging in various industries such as salt production, fishing, and ironworks. The monastery also played a role in the Old Believer movement, resisting ecclesiastical reforms imposed by Patriarch Nikon in the 17th century. Its strategic location made it a target during conflicts, including attacks by the Livonian Order, Swedes, and British during the Crimean War. Despite these challenges, it remained a vital religious institution until the Russian Revolution. [NEWLINE][NEWLINE]In the Soviet era, the monastery was repurposed as a prison camp from 1926 to 1939, serving as a precursor to the Gulag system. During this period, many religious structures were damaged or destroyed. After the collapse of the Soviet Union, monastic life was revived in the 1990s, and extensive restoration efforts have been undertaken. Today, the monastery is a UNESCO World Heritage Site, recognized for its historical and architectural significance. The complex includes the Solovetsky Kremlin, surrounded by massive stone walls and towers, and several churches and monastic buildings dating from the 16th to early 20th centuries. It stands as a testament to the resilience and spiritual heritage of the Russian Orthodox Church in the harsh northern environment.'),
			('TXT_KEY_BUILDING_SOLOVIETSKY_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_SOLOVIETSKY_HELP_CUT', '[COLOR_YIELD_FOOD]Solovietsky Monastery[ENDCOLOR] is very universal project. New cadet school (+2[ICON_GREAT_ADMIRAL]) and advanced dockyards (+25%[ICON_PRODUCTION]/[COLOR_YIELD_GOLD]Military Naval[ENDCOLOR]; +5[ICON_STRENGTH]; +50 HP) can greatly support your army, and from the other hand, lonely monastery (+2[ICON_PEACE]) should bring a little bit of a peace. All of these functions in an inaccessible [COLOR_CITY_BLUE]Tundra[ENDCOLOR] region (+1[ICON_PRODUCTION], +1[ICON_PEACE]/[COLOR_CITY_BLUE]Tile[ENDCOLOR]), and such a distant spot can be ideal for a secret labor camp (10%[ICON_PRODUCTION] into [ICON_FOOD]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Fealty Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Tundra[ENDCOLOR], [COLOR_CYAN]Coast[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_SOLOVIETSKY_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);		
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Fealty Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Coast[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_SOLOVIETSKY_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);		
