-- Siku Quanshu
INSERT INTO Language_en_US 
			(Tag,												Text)
VALUES		('TXT_KEY_BUILDING_SIKU_QUANSHU',					'Siku Quanshu'),
			('TXT_KEY_WONDER_SIKU_QUANSHU_QUOTE',				'[NEWLINE]"I have always imagined that Paradise will be a kind of a Library."[NEWLINE] - Jorge Luis Borges[NEWLINE]'),
			('TXT_KEY_BUILDING_SIKU_QUANSHU_PEDIA',				'The Siku Quanshu, often translated as the Complete Library in Four Sections, is one of the most ambitious literary projects in Chinese history. Commissioned by the Qianlong Emperor of the Qing dynasty in 1772, it aimed to compile, preserve, and systematize all known Chinese texts. Over a period of more than a decade, thousands of scholars meticulously collected works spanning history, philosophy, literature, science, and art. The resulting compilation encompassed approximately 36,000 volumes, covering more than 79,000 individual works, making it the largest collection of writings in Chinese history. The project also reflected the political and cultural goals of the Qing dynasty, as it sought to promote orthodox Confucian values while suppressing dissenting or heterodox views, with certain texts being edited or even banned from inclusion. [NEWLINE][NEWLINE]The Siku Quanshu is organized into four main sections, which give the work its name: Jing (Classics), Shi (History), Zi (Philosophy), and Ji (Literature). Each section was further divided into subcategories to systematically arrange texts by subject and genre, providing scholars with a comprehensive reference for study and research. Manuscripts of the collection were handwritten and copied into seven complete sets, which were stored in specially designated libraries across China, ensuring preservation and accessibility for future generations. Beyond its role as a repository of knowledge, the Siku Quanshu is also a cultural monument, reflecting the intellectual ambitions, bibliographic rigor, and imperial authority of 18th-century China. Its legacy continues to influence Chinese historiography, literature, and library science to this day.'),
			('TXT_KEY_BUILDING_SIKU_QUANSHU_HELP',				''),
			('TXT_KEY_THEMING_BONUS_SIKU_QUANSHU_COMPOSITION',	'Written legacy of all dynasties'),
			('TXT_KEY_THEMING_BONUS_SIKU_QUANSHU_ERAS',			'Literature of all time'),
			('TXT_KEY_THEMING_BONUS_SIKU_QUANSHU_OWNER',		'Literature from people'),
			('TXT_KEY_THEMING_BONUS_SIKU_QUANSHU_WRITINGS',		'Interesting composition of writings'),
			('TXT_KEY_THEMING_BONUS_SIKU_QUANSHU_HELP',			'To maximize your bonus, make sure all the Great Work Slots are all filled with Literature created by You, and from different Eras.');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_SIKU_QUANSHU_HELP_CUT', '[COLOR_YIELD_FOOD]Siku Quanshu[ENDCOLOR] holds knowledge, creations and history of your empire (4[ICON_GW_WRITING], if themed: [ICON_RESEARCH], [ICON_CULTURE]) automatically raising its value and importance (+1[ICON_RESEARCH], +1[ICON_CULTURE]/[ICON_GREAT_WORK][ICON_GREAT_WORK]). This overwhelming collection must be catalogued, secured and preserved from devastation under the eyes of experts (2 slots for [ICON_WRITER]; +1[ICON_RESEARCH]/[ICON_WRITER][ICON_WRITER]) so your charges could benefit of it for many years after your glorious death (+2[ICON_RESEARCH]; -1[ICON_HAPPINESS_3] Illiteracy).'
FROM Language_en_US WHERE Tag = 'TXT_KEY_BUILDING_SIKU_QUANSHU_HELP';
				
