-- Brooklyn Bridge
INSERT INTO Language_en_US 
			(Tag,								Text)
VALUES		('TXT_KEY_BUILDING_BROOKLYN',		'Brooklyn Bridge'),
			('TXT_KEY_WONDER_BROOKLYN_QUOTE',	'[NEWLINE]"Scientists are people who build the Brooklyn Bridge and then buy it."[NEWLINE] - William F. Buckley Jr.[NEWLINE]'),
			('TXT_KEY_BUILDING_BROOKLYN_PEDIA',	'The Brooklyn Bridge, completed in 1883, is one of the most iconic landmarks of New York City and a marvel of 19th-century engineering. Designed by John Augustus Roebling, a German-born engineer, it was originally intended to connect the cities of New York (Manhattan) and Brooklyn over the East River, facilitating commerce and transportation between the two rapidly growing areas. Tragically, Roebling died from an accident during the early stages of construction, and his son, Washington Roebling, took over the project. Washington himself suffered from decompression sickness, leaving much of the on-site management to his wife, Emily Warren Roebling, who played a crucial role in supervising the construction. At the time of its completion, the Brooklyn Bridge was the longest suspension bridge in the world, stretching 1,595 feet across the river, and it symbolized technological progress and the ambition of an emerging modern America. [NEWLINE][NEWLINE]Structurally, the Brooklyn Bridge combines stone towers with steel cable suspension, representing an innovative hybrid of design that influenced bridge construction for decades. Its Gothic-style arches and massive granite piers give it a distinctive aesthetic, while its wide pedestrian walkway offers stunning views of Manhattan and Brooklyn. The bridge carries both vehicular and pedestrian traffic and has become a cultural and historical icon, featured in countless films, photographs, and works of art. Beyond its practical function, the Brooklyn Bridge stands as a testament to human ingenuity, determination, and the collaborative effort required to overcome engineering challenges in an era before modern construction machinery and safety standards. [NEWLINE]During scares of stability of the bridge in 1884, P.T. Barnum lead a herd of 21 elephants from his circus across the bridge. The bridge also has been used for exoduses of people following events such as 9/11, during which circumstances the bridge wobbled in a similar manner to the Millenium bridge in London.'),
			('TXT_KEY_BUILDING_BROOKLYN_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_BROOKLYN_HELP_CUT', '[COLOR_YIELD_FOOD]Brooklyn Bridge[ENDCOLOR] is an urban landscape often presented on movies (+4[ICON_TOURISM]). Its construction connected isolated areas (+1[ICON_INTERNATIONAL_TRADE]) increasing cultural migration (+2[ICON_CULTURE]), and it proved great skill of its engineers (+1[ICON_RESEARCH]; 50[ICON_PRODUCTION], 50[ICON_RESEARCH]/[ICON_GREAT_PEOPLE] expend). This link is a reflection of advancing industrialization (2%[ICON_GREAT_DIPLOMAT] progress/[COLOR_YIELD_FOOD]Industrial (or later) Building[ENDCOLOR] construction; +1[ICON_PRODUCTION]) and progressing optimizm (20[ICON_INFLUENCE]/[ICON_CITY_STATE][ICON_CITY_STATE]).';
				
