-- Trans-Siberian Railway
INSERT INTO Language_en_US 
			(Tag,											Text)
VALUES		('TXT_KEY_BUILDING_SIBERIAN_RAILWAY',			'Trans-Siberian Railway'),
			('TXT_KEY_WONDER_SIBERIAN_RAILWAY_QUOTE',		'[NEWLINE]"The Trans-Siberian is more than just a railway. It''s a journey into the psyche of modern Russia; a triumph of engineering; a movable feast through the largest - and, perhaps, most mysterious - nation on Earth."[NEWLINE] - Gavin Haines[NEWLINE]'),
			('TXT_KEY_BUILDING_SIBERIAN_RAILWAY_PEDIA',		'The Trans-Siberian Railway is a monumental rail network that spans the vast expanse of Russia, connecting Moscow in the west to Vladivostok on the Pacific coast, covering a distance of over 9,200 kilometers (about 5,700 miles). Its construction began in 1891 under the reign of Tsar Alexander III and was completed in 1916 during World War I, although various sections were operational before full completion. The railway was built to strengthen economic integration, military mobility, and political control over the remote regions of Siberia, which were rich in natural resources but sparsely populated. The project involved immense logistical challenges, including harsh climates, difficult terrain, and labor shortages, yet it became a symbol of Russian ambition and engineering prowess. Over time, the Trans-Siberian Railway has played a crucial role in the development of Siberia, facilitating migration, trade, and communication across one of the world''s most geographically challenging regions. [NEWLINE][NEWLINE]The railway is celebrated not only for its scale but also for its engineering achievements, featuring extensive bridges, tunnels, and stations designed to endure extreme temperature fluctuations and permafrost conditions. It passes through diverse landscapes, including dense forests, vast plains, and the Ural Mountains, providing passengers with a unique perspective on Russia''s geographic and cultural diversity. Beyond freight and passenger transport, the Trans-Siberian Railway has become an iconic symbol of adventure and exploration, attracting travelers from around the world seeking to experience one of the longest continuous rail journeys on Earth. Today, it continues to serve as a vital artery for economic activity, connecting Russia''s European and Asian regions while preserving its historical and cultural significance.'),
			('TXT_KEY_BUILDING_SIBERIAN_RAILWAY_HELP',		''),
			('TXT_KEY_PROMOTION_SIBERIAN_RAILWAY',			'Trans-Siberian Railway'),
			('TXT_KEY_PROMOTION_SIBERIAN_RAILWAY_HELP',		'Double [ICON_MOVES]Movement [COLOR:255:230:85:255]on Tundra and Snow[ENDCOLOR].');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_SIBERIAN_RAILWAY_HELP_CUT', '[COLOR_YIELD_FOOD]Trans-Siberian Railway[ENDCOLOR] can take you to remote wilderness ([COLOR_WATER_TEXT]Trans-Siberian Railway[ENDCOLOR]/[COLOR_YIELD_GOLD]Land[ENDCOLOR]) allowing industry to expand into inhospitable regions (+15%[ICON_GOLD]/[ICON_CONNECTED][ICON_CONNECTED], [ICON_INDUSTRIAL_CONNECTED][ICON_INDUSTRIAL_CONNECTED]). This long connection supports new facilities increasing the value of all modern [COLOR_GREY]Strategic[ENDCOLOR] resources on your territory (+5[ICON_GOLDEN_AGE]/[ICON_RES_COAL][ICON_RES_COAL], [ICON_RES_OIL][ICON_RES_OIL], [ICON_RES_ALUMINUM][ICON_RES_ALUMINUM], [ICON_RES_URANIUM][ICON_RES_URANIUM]) and giving new workplaces for your extending empire (+25%[ICON_WORKER] Worker Rate).';
				
