-- Zocalo
INSERT INTO Language_en_US 
			(Tag,								Text)
VALUES		('TXT_KEY_BUILDING_ZOCALO',			'Zócalo'),
			('TXT_KEY_WONDER_ZOCALO_QUOTE',		'[NEWLINE]"The Zócalo is a magnificent space, at least four times the size of Trafalagar Square, with the National Palace on one side, the huge cathedral on the other, and in one corner part of the old Aztec City so brutally destroyed by Hernan Cortez and the Conquistadores."[NEWLINE] - Jeremy Corbyn[NEWLINE]'),
			('TXT_KEY_BUILDING_ZOCALO_PEDIA',	'The Zócalo, officially known as Plaza de la Constitución, is the central square of Mexico City and one of the largest public plazas in the world. Its history stretches back over 700 years, originating as the main ceremonial center of the Aztec city of Tenochtitlán. Following the Spanish conquest in the early 16th century, the plaza was redesigned and became the heart of the colonial capital, serving as a political, religious, and social hub. Over centuries, it has been the site of countless historical events, including political rallies, military parades, and cultural celebrations, reflecting the evolving identity of Mexico. Its name, "Zócalo", which originally referred to the base of an uncompleted monument, has become synonymous with the plaza itself. [NEWLINE][NEWLINE]The Zócalo is surrounded by some of Mexico City''s most significant landmarks, including the Metropolitan Cathedral, the National Palace, and historic colonial-era buildings, giving it immense architectural and cultural importance. The open space of the plaza is used for public gatherings, concerts, festivals, and demonstrations, making it a dynamic center of civic life. With its vast dimensions and historical layers, the Zócalo not only serves as a physical and symbolic heart of Mexico City but also embodies the nation''s rich cultural heritage, blending pre-Hispanic, colonial, and modern influences in a single, iconic space.'),
			('TXT_KEY_BUILDING_ZOCALO_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_ZOCALO_HELP_CUT', '[COLOR_YIELD_FOOD]Zócalo[ENDCOLOR] keeps bloody past alive (+2[ICON_TOURISM]; +2[ICON_TOURISM]/all [COLOR_YIELD_FOOD]Monuments[ENDCOLOR]). It hosted important religious facilities of tribes (+2[ICON_PEACE]) that through different measures ([COLOR_YIELD_GOLD]free [ICON_DIPLOMAT][ENDCOLOR]; 1 slot for [ICON_CIVIL_SERVANT]) were replaced by more advanced civilizations. This huge square constructed on their ashes now serves as a religious (+1[ICON_PEACE]/[ICON_CIVIL_SERVANT][ICON_CIVIL_SERVANT]) and diplomatic center (+10%[ICON_PRODUCTION]/[COLOR_YIELD_GOLD]Diplomatic[ENDCOLOR]) commemorating this difficult memory of our times.';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Flat[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Plains[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Lake[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_ZOCALO_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Flat[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Lake[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_ZOCALO_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
