-- Kew Gardens
INSERT INTO Language_en_US 
			(Tag,									Text)
VALUES		('TXT_KEY_BUILDING_KEW_GARDENS',		'Kew Gardens'),
			('TXT_KEY_WONDER_KEW_GARDENS_QUOTE',	'[NEWLINE]"Stand in nature before anyone else has woken and most people find something to believe in."[NEWLINE] - Tor Udall[NEWLINE]'),
			('TXT_KEY_BUILDING_KEW_GARDENS_PEDIA',	'Kew Gardens, officially known as the Royal Botanic Gardens, Kew, is a world-renowned botanical garden located in southwest London, England. Its origins date back to 1759 when Princess Augusta, mother of King George III, established a royal garden at Kew. Over the centuries, it evolved from a private royal estate into a scientific and public institution dedicated to the study and conservation of plants. Kew Gardens played a pivotal role during the British Empire in collecting and classifying plants from around the world, contributing to botanical research, agriculture, and horticulture. In 1840, the gardens were officially opened to the public, and in 2003, Kew was designated a UNESCO World Heritage Site in recognition of its historical, scientific, and cultural significance. [NEWLINE][NEWLINE]Covering over 300 acres, Kew Gardens features a remarkable variety of landscapes, including formal gardens, woodlands, and extensive glasshouses such as the iconic Palm House and Temperate House, which house thousands of plant species from different climates. The gardens are a center for botanical research, conservation, and education, maintaining one of the largest and most diverse plant collections in the world. Visitors can explore themed gardens, treetop walkways, and ornamental ponds, making it both a scientific resource and a popular recreational destination. Kew Gardens exemplifies the intersection of natural beauty, scientific inquiry, and cultural heritage, inspiring generations of botanists, horticulturists, and visitors from around the globe.'),
			('TXT_KEY_BUILDING_KEW_GARDENS_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_KEW_GARDENS_HELP_CUT', '[COLOR_YIELD_FOOD]Kew Gardens[ENDCOLOR], filled with thousands of plants and human devotion to study their behaviour (10%[ICON_FOOD] into [ICON_RESEARCH]), creates rich database and tries to increase [COLOR_CITY_BROWN]Farms[ENDCOLOR] efficiency in your empire (+1[ICON_FOOD], +1[ICON_RESEARCH], +1[ICON_TOURISM]/[COLOR_CITY_BROWN]Tile in Empire[ENDCOLOR]). Your research program can be greatly boosted by encouraged eco-visitors (+3[ICON_GREAT_SCIENTIST]) and can serve as a tourist attraction for people who want to see new amazing species (10%[ICON_RESEARCH] into [ICON_TOURISM]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Rationalism Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Building: [COLOR_CYAN]Agribusiness[ENDCOLOR], [COLOR_CYAN]Garden[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_KEW_GARDENS_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Rationalism Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Building: [COLOR_CYAN]Agribusiness[ENDCOLOR], [COLOR_CYAN]Garden[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_KEW_GARDENS_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
