-- Monte Carlo Casino
INSERT INTO Language_en_US 
			(Tag,									Text)
VALUES		('TXT_KEY_BUILDING_MONTE_CARLO',		'Monte Carlo Casino'),
			('TXT_KEY_WONDER_MONTE_CARLO_QUOTE',	'[NEWLINE]"Luck was a servant and not a master. Luck had to be accepted with a shrug or taken advantage of up to the hilt. But it had to be understood and recognized for what it was and not confused with a faulty appreciation of the odds, for, at gambling, the deadly sin is to mistake bad play for bad luck."[NEWLINE] - Ian Fleming[NEWLINE]'),
			('TXT_KEY_BUILDING_MONTE_CARLO_PEDIA',	'The Monte Carlo Casino, officially known as Casino de Monte-Carlo, is an iconic gambling and entertainment complex located in the principality of Monaco. Its history dates back to the mid-19th century when Charles III of Monaco sought to rescue the country from financial difficulties by promoting tourism and establishing a gambling house. The casino officially opened in 1863 and was designed by the renowned architect Charles Garnier, who also designed the Paris Opera House. Over time, it became a symbol of luxury, attracting European aristocracy, wealthy tourists, and celebrities. The Monte Carlo Casino not only contributed significantly to Monaco''s economy but also helped establish Monaco as a glamorous and high-profile destination on the Mediterranean coast. [NEWLINE][NEWLINE]Architecturally, the Monte Carlo Casino is renowned for its opulent Belle Époque style, featuring grand halls, intricate frescoes, marble staircases, and ornate chandeliers. The complex includes gaming rooms, theaters, and gardens, offering a combination of entertainment and aesthetic grandeur. Its gaming rooms host a variety of table games and slot machines, while the surrounding area features luxury hotels, boutiques, and the famous harbor, enhancing the experience of sophistication and exclusivity. Beyond its role as a gambling venue, the casino has become a cultural landmark, inspiring films, literature, and popular imagination, and continues to epitomize the elegance, wealth, and allure associated with Monte Carlo.'),
			('TXT_KEY_BUILDING_MONTE_CARLO_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_MONTE_CARLO_HELP_CUT', 'Casino of [COLOR_YIELD_FOOD]Monte Carlo[ENDCOLOR] lures people with quick fortune gain (20%[ICON_GOLD] Spent into [ICON_TOURISM]). Gambling capital (+10%[ICON_GOLD][ICON_GOLD]) attracts tourists and their money to the most famous [COLOR_YIELD_FOOD]Hotels[ENDCOLOR] ([COLOR_YIELD_FOOD]free[ENDCOLOR]; +2[ICON_GOLD][ICON_GOLD], +2[ICON_TOURISM][ICON_TOURISM]), and even though its presence can be destructive or sometimes covers shady dealings, you should turn a blind eye to all of that for the good of your empire (33%[ICON_TOURISM] into [ICON_GOLD]).';
				
