-- Ruhr Valley
INSERT INTO Language_en_US 
			(Tag,									Text)
VALUES		('TXT_KEY_BUILDING_RUHR_VALLEY',		'Ruhr Valley'),
			('TXT_KEY_WONDER_RUHR_VALLEY_QUOTE',	'[NEWLINE]"Art without engineering is dreaming. Engineering without art is calculating."[NEWLINE] - Steven Roberts[NEWLINE]'),
			('TXT_KEY_BUILDING_RUHR_VALLEY_PEDIA',	'The Ruhr Valley, located in western Germany along the Ruhr River, is one of Europe''s most historically significant industrial regions. Its development as an industrial hub began in the early 19th century, fueled by abundant coal deposits and the expansion of railways and waterways, which facilitated the transport of raw materials. By the late 19th and early 20th centuries, the Ruhr Valley had become the heart of Germany''s coal, steel, and chemical industries, driving rapid urbanization and economic growth. The region played a central role during both World Wars due to its industrial output, making it strategically important and a frequent target during conflicts. After World War II, the Ruhr Valley became a symbol of Germany''s post-war economic recovery, particularly during the Wirtschaftswunder, or "economic miracle", and it remains a vital economic area today. [NEWLINE][NEWLINE]The Ruhr Valley''s landscape is a unique blend of industrial infrastructure, urban centers, and cultural sites. It is characterized by coal mines, steel mills, factories, and extensive railway networks, alongside rivers and canals that were essential for industrial transport. Over time, many former industrial sites have been transformed into museums, cultural centers, and recreational areas, reflecting a shift from heavy industry to service-oriented and cultural uses. Cities such as Essen, Dortmund, and Duisburg exemplify this transformation, combining historical industrial architecture with modern urban development. The Ruhr Valley thus represents both the historical engine of German industrialization and a contemporary example of industrial heritage preservation and urban regeneration.'),
			('TXT_KEY_BUILDING_RUHR_VALLEY_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_RUHR_VALLEY_HELP_CUT', 'Abundant [COLOR_YIELD_FOOD]Ruhr Valley[ENDCOLOR] agglomeration (+1[ICON_SWAP] City Working Range) is literally an industrial heart of whole country, keeping it alive thanks to riches hidden by Mother Earth (+10%[ICON_PRODUCTION][ICON_PRODUCTION]). With new infrastructure and recent discoveries of [COLOR_GREY]Coal[ENDCOLOR] deposits (1[ICON_RES_COAL](3) spawned; +1[ICON_GOLD], +1[ICON_GOLDEN_AGE]/[ICON_RES_COAL][ICON_RES_COAL]) it perfectly raises your productiveness and spreads well-trained workforce accross all your [COLOR_CITY_BROWN]Mines[ENDCOLOR] and [COLOR_CITY_BROWN]Quarries[ENDCOLOR] (+1[ICON_PRODUCTION]/[COLOR_CITY_BROWN]Tile in Empire[ENDCOLOR]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Industry Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]River[ENDCOLOR][NEWLINE][ICON_BULLET]City: [COLOR_CYAN]place for [ICON_RES_COAL][ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_RUHR_VALLEY_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Industry Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]River[ENDCOLOR][NEWLINE][ICON_BULLET]City: [COLOR_CYAN]place for [ICON_RES_COAL][ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_RUHR_VALLEY_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
