-- Banff Springs Hotel
INSERT INTO Language_en_US 
			(Tag,								Text)
VALUES		('TXT_KEY_BUILDING_BANFF',			'Banff Springs Hotel'),
			('TXT_KEY_WONDER_BANFF_QUOTE',		'[NEWLINE]"A national park is not a playground. It''s a sanctuary for nature and for humans who will accept nature on nature''s own terms."[NEWLINE] - Michael Frome[NEWLINE]'),
			('TXT_KEY_BUILDING_BANFF_PEDIA',	'The Banff Springs Hotel, located in Banff National Park, Alberta, Canada, is a historic luxury hotel often referred to as the "Castle in the Rockies". Its origins date back to 1888 when the Canadian Pacific Railway commissioned its construction to promote tourism along the railway and attract visitors to the Canadian Rockies. Designed initially by architect Bruce Price and later expanded by several others, the hotel became a symbol of opulence and the natural beauty of the region. Over the decades, it has hosted royalty, celebrities, and dignitaries, while also playing a key role in the development of tourism in western Canada. Its history reflects both the ambition of the Canadian Pacific Railway and the broader movement to make the Canadian wilderness accessible and appealing to international travelers. [NEWLINE][NEWLINE]Architecturally, the Banff Springs Hotel combines Scottish baronial and château-style design, with steep pitched roofs, turrets, and stone façades that blend harmoniously with the surrounding mountainous landscape. The hotel sits near the Bow River, providing stunning views of the Rockies, and features elegant interiors, luxurious accommodations, and extensive recreational facilities, including golf courses, spas, and hiking trails. Beyond its role as a luxury resort, the hotel has become a cultural and historical landmark, representing the fusion of natural splendor, architectural grandeur, and early Canadian tourism initiatives. Today, it continues to attract visitors from around the world seeking both relaxation and an immersive experience in the Rocky Mountains.'),
			('TXT_KEY_BUILDING_BANFF_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_BANFF_HELP_CUT', '[COLOR_YIELD_FOOD]Banff Springs Hotel[ENDCOLOR] lying in a remarkable nature park full of monumental [COLOR_CITY_BLUE]Mountains[ENDCOLOR] (+5[ICON_GOLD], +5[ICON_TOURISM]/[COLOR_CITY_BLUE]Tile[ENDCOLOR]) is a perfect example how to develop your economy (+1[ICON_GREAT_MERCHANT]; +1[ICON_GOLD], +1[ICON_TOURISM]/[ICON_MERCHANT][ICON_MERCHANT]) in a symbiosis with the environment (+5[ICON_TOURISM]). Such [COLOR_YIELD_FOOD]Hotels[ENDCOLOR] ([COLOR_YIELD_FOOD]free[ENDCOLOR]) are sponsored by the railway companies and have one very important function: to make the long journey pleasant (-1[ICON_HAPPINESS_3] Boredom). Now you can travel with style!';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Industry Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Tundra[ENDCOLOR], [COLOR_CYAN]Mountain (range 2)[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_BANFF_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Industry Finisher[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Tundra[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_BANFF_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
