-- Orszaghaz
INSERT INTO Language_en_US 
			(Tag,										Text) 
VALUES		('TXT_KEY_BUILDING_ORSZAGHAZ',				'Orszaghaz'),
			('TXT_KEY_WONDER_ORSZAGHAZ_QUOTE',			'[NEWLINE]"With self-government is freedom, and with freedom is justice and patriotism."[NEWLINE] - Lajos Kossuth[NEWLINE]'),
			('TXT_KEY_BUILDING_ORSZAGHAZ_PEDIA',		'The Országház, or Hungarian Parliament Building, is the seat of the National Assembly of Hungary and one of Budapest''s most iconic landmarks. Its construction began in 1885 and was completed in 1904, during a period when Hungary was part of the Austro-Hungarian Empire. The building was designed by architect Imre Steindl in a Gothic Revival style, reflecting national pride and Hungary''s growing political and cultural identity. Situated on the banks of the Danube River, the Országház was intended not only as a functional government building but also as a symbol of Hungary''s sovereignty, grandeur, and architectural achievement. Over the years, it has witnessed significant historical events, including political upheavals, revolutions, and ceremonies, cementing its status as a national symbol. [NEWLINE][NEWLINE]Architecturally, the Országház is renowned for its elaborate Gothic Revival design, featuring pointed arches, spires, and a striking central dome that rises over 96 meters, symbolizing the nation''s millennium in 1896. The building stretches 268 meters in length and houses nearly 700 rooms, including the grand staircase, ornate chambers, and the Hungarian Crown Jewels. Its exterior is adorned with statues of Hungarian rulers and national figures, while the interior boasts intricate frescoes, stained glass, and richly decorated halls. Beyond its political function, the Országház serves as a major tourist attraction and a cultural monument, representing Hungary''s architectural heritage, historical continuity, and national identity.'),
			('TXT_KEY_BUILDING_ORSZAGHAZ_HELP',			''),
			('TXT_KEY_GREAT_WORK_HOLY_CROWN',			'Holy Crown of Hungary'),
			('TXT_KEY_GREAT_WORK_HOLY_CROWN_QUOTE',		'[NEWLINE]You desire that which exceeds my humble powers, but I trust[NEWLINE]in the compassion and mercy of the All-powerful God.[NEWLINE] - Saint Stephen[NEWLINE]');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_ORSZAGHAZ_HELP_CUT', '[COLOR_YIELD_FOOD]Orszaghaz[ENDCOLOR] celebrates the unification (+15%[ICON_GOLDEN_AGE][ICON_GOLDEN_AGE]) and praises the history (1[ICON_GW_ART]; [COLOR_CULTURE_STORED]Holy Crown of Hungary[ENDCOLOR]). It uses its majesty to show how democratic rules can make the world better (+1[ICON_DIPLOMAT] League Vote), and that acting alone in the politics is not the most efficient solution (+1[ICON_DIPLOMAT] League Vote/2 DoF or 2 DP). Starting from the first parliamentary session ([COLOR_MAGENTA]free Policy[ENDCOLOR]) your rules are consolidated, spreading the light of a new age.';
				
