-- Polar Expedition
INSERT INTO Language_en_US 
			(Tag,										Text)
VALUES		('TXT_KEY_BUILDING_POLAR_EXPEDITION',		'Polar Expedition'),
			('TXT_KEY_WONDER_POLAR_EXPEDITION_QUOTE',	'[NEWLINE]"Adventure is just bad planning."[NEWLINE] - Roald Amundsen[NEWLINE]'),
			('TXT_KEY_BUILDING_POLAR_EXPEDITION_PEDIA',	'Polar expeditions refer to organized journeys to the Earth''s polar regions—both the Arctic in the north and the Antarctic in the south—undertaken primarily for exploration, scientific research, and geographic discovery. The history of polar expeditions dates back centuries, with early Arctic explorations in the 16th and 17th centuries focusing on discovering the Northwest Passage. The 19th and early 20th centuries marked the "Heroic Age of Polar Exploration", with famous expeditions such as those led by Fridtjof Nansen, Robert Falcon Scott, Roald Amundsen, and Ernest Shackleton. These missions aimed to reach the North Pole or South Pole, chart uncharted territories, and study the extreme environments. Polar expeditions were often perilous, involving harsh weather, treacherous ice, limited supplies, and isolation, yet they contributed significantly to scientific knowledge, including meteorology, glaciology, and polar biology. [NEWLINE][NEWLINE]Modern polar expeditions combine exploration with advanced scientific research, using specialized equipment, satellite navigation, and improved survival technology. In addition to reaching the poles, contemporary expeditions study climate change, wildlife, and ice sheet dynamics, providing valuable data on environmental shifts and global warming. Polar stations and research bases, such as those in Antarctica under international treaties, facilitate year-round scientific work. Beyond their scientific purpose, polar expeditions capture public imagination, symbolizing human endurance, curiosity, and the drive to explore the most extreme and remote regions on Earth. They continue to inspire adventure, international collaboration, and a deeper understanding of our planet''s polar environments.'),
			('TXT_KEY_BUILDING_POLAR_EXPEDITION_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_POLAR_EXPEDITION_HELP_CUT', '[COLOR_YIELD_FOOD]Polar Expedition[ENDCOLOR] vastly explores unvisited [COLOR_CITY_BLUE]Snow[ENDCOLOR] areas (+2[ICON_RESEARCH]/Tile) and looks for new underground [COLOR_GREY]Oil[ENDCOLOR] deposits (1[ICON_RES_OIL](2) and 1[ICON_RES_OIL](3) spawned) hidden by white cover. New research facilities created there will surely expand our knowledge about Earth and its history (+1[ICON_RESEARCH], +1[ICON_GOLDEN_AGE]/[ICON_SCIENTIST][ICON_SCIENTIST]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Snow[ENDCOLOR][NEWLINE][ICON_BULLET]City: [COLOR_CYAN]located near Pole[ENDCOLOR], [COLOR_CYAN]place for [ICON_RES_OIL][ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_POLAR_EXPEDITION_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Snow[ENDCOLOR][NEWLINE][ICON_BULLET]City: [COLOR_CYAN]place for [ICON_RES_OIL][ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_POLAR_EXPEDITION_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);

UPDATE Language_en_US SET Text = REPLACE(Text, 'All requirements (including lua):', 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_MAGENTA]Rationalism Finisher[ENDCOLOR]') WHERE Tag ='TXT_KEY_BUILDING_POLAR_EXPEDITION_HELP' AND EXISTS (SELECT * FROM Community WHERE Type='MW-SETTING-POLICIES' AND Value=1);
