-- Akihabara Electric Town
INSERT INTO Language_en_US 
			(Tag,									Text)
VALUES		('TXT_KEY_BUILDING_AKIHABARA',			'Akihabara Electric Town'),
			('TXT_KEY_WONDER_AKIHABARA_QUOTE',		'[NEWLINE]"It''s akin to the maddest Asian market you''ve ever been in, but instead of selling mangosteens they''re hawking manga and motherboards - and the sellers are not only pushy, they''re prerecorded."[NEWLINE] - "Lonely Planet" about Akihabara[NEWLINE]'),
			('TXT_KEY_BUILDING_AKIHABARA_PEDIA',	'Akihabara Electric Town, located in Tokyo, Japan, is a world-famous district known for its electronics, gaming, and otaku (anime and manga) culture. Its origins trace back to the post-World War II period when the area became a hub for selling household electronics and surplus military radio equipment. Over the decades, Akihabara evolved into a center for cutting-edge technology, with countless shops offering computers, cameras, audio equipment, and later, video games and hobby electronics. By the 1980s and 1990s, the district had established its reputation not only as a marketplace for electronics but also as a cultural hotspot for fans of anime, manga, and video games, earning it the nickname "Electric Town". [NEWLINE][NEWLINE]Today, Akihabara Electric Town is a vibrant blend of modern commerce and pop culture. Towering multi-story electronics stores coexist with small specialty shops, maid cafés, gaming arcades, and anime merchandise stores, creating a unique atmosphere that attracts both tech enthusiasts and tourists. The area is also a center for technology innovation and subcultures, hosting events, exhibitions, and conventions that celebrate Japanese media and gaming culture. Beyond shopping, Akihabara reflects Tokyo''s dynamic fusion of tradition and modernity, offering a glimpse into Japan''s technological prowess and its influence on global pop culture.'),
			('TXT_KEY_BUILDING_AKIHABARA_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_AKIHABARA_HELP_CUT', '[COLOR_YIELD_FOOD]Akihabara Electric Town[ENDCOLOR] is a place, where merchants (2 slots for [ICON_MERCHANT]; +2[ICON_PRODUCTION]/[ICON_MERCHANT][ICON_MERCHANT]) sell all kind of electronic stuff you can imagine. Those [COLOR_YIELD_FOOD]Markets[ENDCOLOR] (+1[ICON_PRODUCTION], +2[ICON_GOLD], +1[ICON_CULTURE]/all [COLOR_YIELD_FOOD]Markets[ENDCOLOR]) work locally, but all those products can be sold abroad through [COLOR_CITY_BROWN]Customs Houses[ENDCOLOR] (+1[ICON_PRODUCTION], +1[ICON_GOLD]/Tile in Empire) supporting electronic industry of the world, as well.';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Improvement: [COLOR_CYAN]Town[ENDCOLOR][NEWLINE][ICON_BULLET]City: [COLOR_CYAN]2 active [ICON_MERCHANT] Merchants[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_AKIHABARA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = ''||Text WHERE Tag ='TXT_KEY_BUILDING_AKIHABARA_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
