-- Hollywood
INSERT INTO Language_en_US 
			(Tag,									Text)
VALUES		('TXT_KEY_BUILDING_HOLLYWOOD',			'Hollywood'),
			('TXT_KEY_WONDER_HOLLYWOOD_QUOTE',		'[NEWLINE]"Hollywood is a place where they''ll pay you a thousand dollars for a kiss and fifty cents for your soul. I know, because I turned down the first offer often enough and held out for the fifty cents."[NEWLINE] - Marilyn Monroe[NEWLINE]'),
			('TXT_KEY_BUILDING_HOLLYWOOD_PEDIA',	'Hollywood, located in Los Angeles, California, is a globally recognized center of the entertainment industry, particularly film and television. Its rise began in the early 20th century when filmmakers were drawn to Southern California for its favorable climate, diverse landscapes, and distance from patent restrictions enforced by the Motion Picture Patents Company on the East Coast. By the 1910s and 1920s, Hollywood had become the heart of the burgeoning American film industry, attracting actors, directors, and producers. The establishment of major studios such as Paramount, Warner Bros., and Universal cemented its status as the epicenter of cinema. Over the decades, Hollywood has not only shaped American popular culture but has also influenced global media trends, becoming synonymous with glamour, celebrity, and creative innovation. [NEWLINE][NEWLINE]Architecturally and culturally, Hollywood is known for iconic landmarks such as the Hollywood Sign, the Walk of Fame, and historic theaters like the TCL Chinese Theatre. The district encompasses production studios, offices, and entertainment venues, making it a hub for both filmmaking and tourism. Hollywood has continually adapted to changes in technology, from the transition to sound films to the rise of digital media and streaming platforms. Beyond its economic and artistic contributions, Hollywood represents a symbol of aspiration and storytelling, reflecting the dreams, ambitions, and cultural narratives of generations worldwide.'),
			('TXT_KEY_BUILDING_HOLLYWOOD_HELP',		'');

INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_HOLLYWOOD_HELP_CUT', 'If you want to make your empire happier, built [COLOR_YIELD_FOOD]Hollywood[ENDCOLOR] (-1[ICON_HAPPINESS_3] Boredom; -5%[ICON_HAPPINESS_3][ICON_HAPPINESS_3] Boredom). It will be a cultural center of your country (+1[ICON_TOURISM]; 75[ICON_TOURISM]/Policy unlock; [COLOR_MAGENTA]free Policy[ENDCOLOR]), that also make profits for you (+1[ICON_GOLD], +1[ICON_CULTURE]/all [COLOR_YIELD_FOOD]Broadcast Towers[ENDCOLOR]; +2[ICON_GOLD], +2[ICON_CULTURE], +2[ICON_TOURISM]/all [COLOR_YIELD_FOOD]Guilds[ENDCOLOR])!';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_UNIT_TEXT]Freedom[ENDCOLOR][NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Coast[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_HOLLYWOOD_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_UNIT_TEXT]Freedom[ENDCOLOR][NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_HOLLYWOOD_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
