-- Concorde
INSERT INTO Language_en_US 
			(Tag,								Text)
VALUES		('TXT_KEY_BUILDING_CONCORDE',		'Concorde'),
			('TXT_KEY_WONDER_CONCORDE_QUOTE',	'[NEWLINE]"I should go to Paris and jump off of the Eiffel Tower. If I took the Concorde, I could be dead three hours earlier."[NEWLINE] - Woody Allen[NEWLINE]'),
			('TXT_KEY_BUILDING_CONCORDE_PEDIA',	'The Concorde was a revolutionary supersonic passenger airliner developed jointly by British Aircraft Corporation (BAC) and Aérospatiale of France, entering service in 1976. Its history traces back to the early 1960s, when both the United Kingdom and France sought to create a high-speed aircraft capable of cutting transatlantic flight times in half. The Concorde could travel at speeds of over Mach 2 (approximately 1,354 mph or 2,180 km/h), making it one of the fastest commercial aircraft ever built. Despite its technological achievements, Concorde faced challenges, including high operating costs, limited seating capacity, and environmental concerns related to noise and fuel consumption. It became a symbol of luxury air travel, primarily serving routes between London, Paris, New York, and Washington, catering to affluent passengers and business travelers. [NEWLINE][NEWLINE]The Concorde was distinguished by its sleek, delta-wing design, drooping nose for improved visibility during takeoff and landing, and afterburning turbojet engines that enabled supersonic flight. Its interior emphasized comfort and exclusivity, with seating for around 100 passengers and attentive service. Although the Concorde was retired in 2003 due to economic and safety considerations, including the aftermath of the Air France Flight 4590 crash in 2000, it remains an icon of aviation history. The aircraft is celebrated for its engineering excellence, aerodynamic innovation, and its role in pushing the boundaries of commercial air travel, leaving a lasting legacy in aerospace design and supersonic transportation.'),
			('TXT_KEY_BUILDING_CONCORDE_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_CONCORDE_HELP_CUT', 'Supersonic airliner [COLOR_YIELD_FOOD]Concorde[ENDCOLOR] drastically increases efficiency in passenger flights and boosts tourism income (+3[ICON_TOURISM]; +3[ICON_TOURISM]/[ICON_RES_OIL][ICON_RES_OIL], [ICON_RES_ALUMINUM][ICON_RES_ALUMINUM]; +25%[ICON_TOURISM] during [ICON_HAPPINESS_1]WLTKD). The world is your oyster (20[ICON_INFLUENCE]/[ICON_CITY_STATE][ICON_CITY_STATE]). Just count the money (+15%[ICON_GOLD]/[ICON_CONNECTED][ICON_CONNECTED], [ICON_INDUSTRIAL_CONNECTED][ICON_INDUSTRIAL_CONNECTED]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Improved Resource: [ICON_RES_ALUMINUM][NEWLINE][ICON_BULLET]City: [COLOR_CYAN]3 active [ICON_ENGINEER] Engineers[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_CONCORDE_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Improved Resource: [ICON_RES_ALUMINUM]'||Text WHERE Tag ='TXT_KEY_BUILDING_CONCORDE_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
