-- Mount Rushmore
INSERT INTO Language_en_US 
			(Tag,								Text)
VALUES		('TXT_KEY_BUILDING_RUSHMORE',		'Mount Rushmore'),
			('TXT_KEY_WONDER_RUSHMORE_QUOTE',	'[NEWLINE]"Guard against the impostures of pretended patriotism." - G. Washington;  "Only lay down true principles, and adhere to them inflexibly." - T. Jefferson;  "The government is us; we are the government, you and I." - T. Roosevelt;  "The dogmas of the quiet past are inadequate to the stormy present." - A. Lincoln[NEWLINE]'),
			('TXT_KEY_BUILDING_RUSHMORE_PEDIA',	'Mount Rushmore, located in the Black Hills of South Dakota, is a monumental sculpture featuring the 60-foot-high faces of four U.S. presidents: George Washington, Thomas Jefferson, Theodore Roosevelt, and Abraham Lincoln. The idea for the memorial was conceived in the early 1920s by historian Doane Robinson, who wanted to promote tourism in South Dakota. Sculptor Gutzon Borglum was commissioned to design and oversee the project, which began in 1927 and continued until 1941. The memorial was carved directly into the granite mountainside using dynamite and traditional sculpting techniques, employing hundreds of workers over the 14-year period. Mount Rushmore was intended to symbolize the birth, growth, development, and preservation of the United States, honoring leaders who played pivotal roles in shaping the nation. [NEWLINE][NEWLINE]The sculpture is not only an engineering and artistic achievement but also a cultural landmark. Its location in the rugged Black Hills offers dramatic views and emphasizes the scale and permanence of the work. Beyond its sheer size and visual impact, Mount Rushmore includes a visitor center, museum, and walking trails that provide educational and historical context. While it serves as a major tourist attraction and a symbol of American democracy and leadership, the site is also part of the ancestral lands of the Lakota Sioux, making it a place of complex historical and cultural significance. Mount Rushmore continues to be a powerful emblem of national identity, artistry, and the intersection of history and landscape.'),
			('TXT_KEY_BUILDING_RUSHMORE_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_RUSHMORE_HELP_CUT', '[COLOR_YIELD_FOOD]Mount Rushmore[ENDCOLOR] is a fantastic artistic creation (1 slot for [ICON_ARTIST]) cut in the [COLOR_CITY_BLUE]Mountain[ENDCOLOR] (+1[ICON_PRODUCTION], +1[ICON_CULTURE], +1[ICON_TOURISM]/Tile). This work is the main reason people visit this part of the world (+1[ICON_CULTURE], +1[ICON_TOURISM]/[ICON_GREAT_WORK][ICON_GREAT_WORK]) and, as an addition, it commemorates 4 greatest people in history of the country (+1[ICON_DIPLOMAT] League Vote).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Mountain (range 2)[ENDCOLOR][NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Forest[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_RUSHMORE_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Mountain (range 2)[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_RUSHMORE_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
