-- Habitat-67
INSERT INTO Language_en_US 
			(Tag,								Text)
VALUES		('TXT_KEY_BUILDING_HABITAT',		'Habitat-67'),
			('TXT_KEY_WONDER_HABITAT_QUOTE',	'[NEWLINE]"A house is made of walls and beams; a home is built with love and dreams."[NEWLINE] - Ralph Waldo Emerson[NEWLINE]'),
			('TXT_KEY_BUILDING_HABITAT_PEDIA',	'Habitat 67 is an iconic housing complex located in Montreal, Quebec, Canada, renowned for its innovative approach to urban living. It was designed by Israeli-Canadian architect Moshe Safdie as part of his thesis project and built as a pavilion for Expo 67, the 1967 World''s Fair. The project was conceived to address the challenges of high-density housing while offering the privacy, greenery, and individuality of suburban homes. Habitat 67 consists of 354 prefabricated concrete modules arranged in a unique, interlocking pattern, creating 146 residential units with terraces, gardens, and open spaces. The complex was revolutionary at the time, blending architectural experimentation with practical considerations for urban living and community design. [NEWLINE][NEWLINE]Architecturally, Habitat 67 is celebrated for its modular construction, geometric forms, and integration with the natural environment. Each unit is designed to maximize sunlight, ventilation, and outdoor space, reflecting Safdie''s vision of combining efficiency with quality of life. The structure''s bold, stacked appearance has made it a symbol of modernist architecture and a landmark of Montreal''s skyline. Beyond its aesthetic appeal, Habitat 67 challenged conventional notions of apartment living and continues to influence architects and urban planners worldwide. Today, it remains a functioning residential complex, attracting attention from tourists, students of architecture, and design enthusiasts eager to study its innovative approach to urban housing.'),
			('TXT_KEY_BUILDING_HABITAT_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_HABITAT_HELP_CUT', '[COLOR_YIELD_FOOD]Habitat-67[ENDCOLOR] fully focuses on turning your city into a paradise. It might become really crowded (+3[ICON_CITIZEN]), but the quality of life improves significantly (-3[ICON_HAPPINESS_3] Urbanization; -2[ICON_HAPPINESS_3] Distress), inhabitants can benefit from better infrastructure (+1[ICON_HAPPINESS_1]/[COLOR_YIELD_FOOD]Garden[ENDCOLOR], [COLOR_YIELD_FOOD]Museum[ENDCOLOR], [COLOR_YIELD_FOOD]Hospital[ENDCOLOR], [COLOR_YIELD_FOOD]Police Station[ENDCOLOR]) and engineers still look for more (+1[ICON_CULTURE]/[ICON_ENGINEER][ICON_ENGINEER]).';
				
