-- Vostok Station
INSERT INTO Language_en_US 
			(Tag,								Text)
VALUES		('TXT_KEY_BUILDING_VOSTOK',			'Vostok Station'),
			('TXT_KEY_WONDER_VOSTOK_QUOTE',		'[NEWLINE]"On the barren shore, and on the lofty ice barrier in the background, myriads of grotesque penguins squawked and flapped their fins; while many fat seals were visible on the water, swimming or sprawling across large cakes of slowly drifting ice."[NEWLINE] - H.P. Lovecraft[NEWLINE]'),
			('TXT_KEY_BUILDING_VOSTOK_PEDIA',	'Vostok Station is a Russian (formerly Soviet) research station located in East Antarctica, near the Southern Pole of Cold. Established in 1957 during the International Geophysical Year, it was built to conduct scientific research in one of the most remote and extreme environments on Earth. The station is operated by the Arctic and Antarctic Research Institute and has been continuously used for studies in glaciology, meteorology, seismology, and atmospheric sciences. Vostok Station gained global attention in 2012 when scientists reported drilling into Lake Vostok, a subglacial lake buried under more than 4 kilometers of ice, which has remained isolated for millions of years. The station''s history reflects the geopolitical and scientific ambitions of the Soviet Union during the Cold War, as well as ongoing international interest in understanding Antarctica''s climate and geology. [NEWLINE][NEWLINE]The station is characterized by its extreme environmental conditions, with winter temperatures averaging around −70°C (−94°F) and wind speeds that can exceed 50 meters per second. Its infrastructure includes insulated living quarters, laboratories, power generation facilities, and communication systems, all designed to withstand the harsh Antarctic climate. Despite the isolation and challenging conditions, Vostok Station serves as a hub for long-term climate research, ice-core sampling, and studies of extreme microbial life. Beyond its scientific significance, it symbolizes human perseverance and curiosity, providing critical insights into Earth''s climate history, ice dynamics, and the possibility of life in extreme environments.'),
			('TXT_KEY_BUILDING_VOSTOK_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_VOSTOK_HELP_CUT', '[COLOR_YIELD_FOOD]Vostok Station[ENDCOLOR], built in the coldest part of the world can perform many unusual researches (3 slots for [ICON_SCIENTIST]) related to [COLOR_CITY_BLUE]Snow[ENDCOLOR] (+1[ICON_FOOD], +1[ICON_PRODUCTION], +4[ICON_RESEARCH]/Tile) or underground [COLOR_CITY_GREEN]Lakes[ENDCOLOR] (+5[ICON_RESEARCH]/Tile). All samples are analyzed worldwide in all kind of research facilities (+3[ICON_FOOD]/all [COLOR_YIELD_FOOD]Medical Labs[ENDCOLOR]; +2[ICON_RESEARCH]/all [COLOR_YIELD_FOOD]Research Labs[ENDCOLOR]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Snow[ENDCOLOR][NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Flat[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_VOSTOK_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_CYAN]Snow[ENDCOLOR][NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Flat[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_VOSTOK_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
