-- Milestii Mici Winery
INSERT INTO Language_en_US 
			(Tag,										Text)
VALUES		('TXT_KEY_BUILDING_MILESTII_MICI',			'Milestii Mici Winery'),
			('TXT_KEY_WONDER_MILESTII_MICI_QUOTE',		'[NEWLINE]"It''s quite true I''m not drinking anymore; however, I''m not drinking any less either."[NEWLINE] - W.C. Fields[NEWLINE]'),
			('TXT_KEY_BUILDING_MILESTII_MICI_PEDIA',	'Milestii Mici Winery, located near Chişinău in Moldova, is renowned for housing one of the largest wine cellars in the world. The origins of the winery date back to the 1960s when extensive limestone tunnels, initially created for mining purposes, were repurposed for wine storage. Spanning over 200 kilometers (124 miles) underground—though only about 55 kilometers are currently in use—these cellars provide ideal conditions for aging wine, with a constant temperature of 12–14°C (54–57°F) and humidity around 85–95%. Milestii Mici became a symbol of Moldovan wine culture, showcasing the country''s winemaking expertise and playing a central role in the export of Moldovan wines to international markets. [NEWLINE][NEWLINE]The winery is famous not only for its scale but also for its vast collection of vintage wines, with millions of bottles stored in organized rows along the underground tunnels. The collection includes local Moldovan varietals such as Fetească Neagră and Rara Neagră, as well as international wines. Milestii Mici has become a popular tourist destination, offering guided tours, tastings, and events in its unique subterranean environment. Its combination of historical ingenuity, natural storage conditions, and extensive wine heritage makes the winery a remarkable example of both industrial adaptation and viticultural excellence, attracting wine enthusiasts from around the globe.'),
			('TXT_KEY_BUILDING_MILESTII_MICI_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_MILESTII_MICI_HELP_CUT', '[COLOR_YIELD_FOOD]Milestii Mici Winery[ENDCOLOR] contains the finest wines from all over the Europe, and the world, too (+1[ICON_FOOD], +1[ICON_GOLD]/[ICON_CITY_STATE] Friend; +2[ICON_FOOD], +1[ICON_PRODUCTION], +2[ICON_GOLD]/[ICON_CITY_STATE] Ally). Hired merchants do their best to gather them all in one place (+1[ICON_FOOD], +1[ICON_PRODUCTION]/[ICON_MERCHANT][ICON_MERCHANT]) and all these traded goods can improve overall prices of new investments (-10[ICON_GOLD][ICON_GOLD] Hurry Cost Modifiers).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Forest[ENDCOLOR], [COLOR_NEGATIVE_TEXT]Water[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_MILESTII_MICI_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]Forest[ENDCOLOR], [COLOR_NEGATIVE_TEXT]Water[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_MILESTII_MICI_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
