-- JFK Space Center
INSERT INTO Language_en_US 
			(Tag,							Text)
VALUES		('TXT_KEY_BUILDING_JFK',		'JFK Space Center'),
			('TXT_KEY_WONDER_JFK_QUOTE',	'[NEWLINE]"The view of Earth is absolutely spectacular, and the feeling of looking back and seeing your planet as a planet is just an amazing feeling. It''s a totally different perspective, and it makes you appreciate, actually, how fragile our existence is."[NEWLINE] - Sally Ride[NEWLINE]'),
			('TXT_KEY_BUILDING_JFK_PEDIA',	'The Kennedy Space Center (KSC), located on Merritt Island in Florida, is the primary launch center for human spaceflight in the United States. Established in 1962 by NASA, it was created to support the Apollo program, which aimed to land astronauts on the Moon, and to advance the nation''s space exploration goals during the Space Race with the Soviet Union. The center is named after President John F. Kennedy, who famously set the national goal of sending an American safely to the Moon before the end of the 1960s. Over the decades, KSC has been the site of historic missions, including the Apollo 11 lunar landing in 1969, the Space Shuttle program beginning in 1981, and subsequent unmanned and crewed missions that have expanded human understanding of space and technology. [NEWLINE][NEWLINE]Kennedy Space Center is a sprawling complex that includes launch pads, vehicle assembly buildings, mission control facilities, and astronaut training areas. It also features the Kennedy Space Center Visitor Complex, which offers exhibits, simulators, and tours to educate the public about space exploration. The center is equipped with advanced technology to handle the preparation, assembly, and launching of spacecraft, while supporting research in propulsion, materials, and astronautics. Beyond its operational role, KSC serves as a symbol of human ingenuity, scientific achievement, and the aspiration to explore beyond our planet, attracting engineers, scientists, and tourists inspired by space exploration.'),
			('TXT_KEY_BUILDING_JFK_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_JFK_HELP_CUT', '[COLOR_YIELD_FOOD]JFK Space Center[ENDCOLOR] is a voice of freedom that desires reaching the sky (+2[ICON_BULLET]Air slots; +20%[ICON_PRODUCTION]/[COLOR_YIELD_GOLD]Spaceship Part[ENDCOLOR]). Even though it is a military project, even civilians may benefit from new technologies (-2[ICON_HAPPINESS_3] Illiteracy; [COLOR_CYAN]Satellites[ENDCOLOR]: +3[ICON_RESEARCH]). But not only new technologies, yet also new reforms might come with it ([COLOR_MAGENTA]free Policy[ENDCOLOR]).';
				
