-- Anitkabir
INSERT INTO Language_en_US 
			(Tag,									Text)
VALUES		('TXT_KEY_BUILDING_ANITKABIR',			'Anitkabir'),
			('TXT_KEY_WONDER_ANITKABIR_QUOTE',		'[NEWLINE]"Peace at home, peace in the world."[NEWLINE] - Mustafa Kemal Atatürk[NEWLINE]'),
			('TXT_KEY_BUILDING_ANITKABIR_PEDIA',	'Anitkabir is the mausoleum of Mustafa Kemal Atatürk, the founder and first President of the Republic of Turkey, located in Ankara. Its construction began in 1944 and was completed in 1953, following an architectural competition that emphasized both grandeur and symbolic meaning. Designed by architects Emin Onat and Orhan Arda, Anitkabir was conceived as a national monument to honor Atatürk''s leadership in the Turkish War of Independence and his pivotal role in establishing a secular, modern Turkish state. The site was deliberately placed on a hill overlooking the city, symbolizing Atatürk''s vision and enduring influence on the nation. Anitkabir has since become a central place for national ceremonies, commemorations, and public homage. [NEWLINE][NEWLINE]The mausoleum combines elements of modern and classical architecture, with a massive ceremonial plaza, grand colonnades, and an imposing main hall housing Atatürk''s tomb. Surrounding the structure are museums exhibiting personal belongings, documents, and photographs related to Atatürk''s life and Turkey''s founding era. The complex also features symbolic reliefs and inscriptions reflecting themes of independence, unity, and progress. Beyond its architectural and historical significance, Anitkabir serves as a cultural and educational site, attracting millions of visitors annually and standing as a powerful symbol of Turkish identity, national pride, and the enduring legacy of Mustafa Kemal Atatürk.'),
			('TXT_KEY_BUILDING_ANITKABIR_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_ANITKABIR_HELP_CUT', '[COLOR_YIELD_FOOD]Anitkabir[ENDCOLOR] fullfils a dream about world at peace. It makes diplomatic contacts much easier (+50%[ICON_PRODUCTION]/[COLOR_YIELD_GOLD]Diplomatic[ENDCOLOR]) and negotiations in World Congress more favourable to your side (+1[ICON_DIPLOMAT] League Vote; +1[ICON_DIPLOMAT] League Vote/controlled Enemy Capital). People will love you and your politics ([COLOR_MAGENTA]free Policy[ENDCOLOR]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_UNIT_TEXT]Autocracy[ENDCOLOR][NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Terrain: [COLOR_NEGATIVE_TEXT]Coast[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_ANITKABIR_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_UNIT_TEXT]Autocracy[ENDCOLOR][NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_ANITKABIR_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
