-- Thule Air Base
INSERT INTO Language_en_US 
			(Tag,								Text)
VALUES		('TXT_KEY_BUILDING_THULE',			'Thule Air Base'),
			('TXT_KEY_WONDER_THULE_QUOTE',		'[NEWLINE]"A modern, autonomous, and thoroughly trained Air Force in being at all times will not alone be sufficient, but without it, there can be no national security."[NEWLINE] - Henry H. Arnold[NEWLINE]'),
			('TXT_KEY_BUILDING_THULE_PEDIA',	'Thule Air Base, located in northwestern Greenland, is the United States'' northernmost military installation, strategically positioned to monitor and defend North American airspace during the Cold War and beyond. The base was established in 1951 as part of a U.S.-Danish agreement to enhance early warning capabilities against potential Soviet attacks, particularly nuclear threats. Thule served as a key site in the development of radar and missile defense systems, including the Distant Early Warning (DEW) Line, which formed a chain of radar stations across the Arctic. Its history reflects the geopolitical tensions of the Cold War era and the strategic importance of the Arctic region in global defense planning. [NEWLINE][NEWLINE]Thule Air Base encompasses extensive infrastructure, including runways capable of handling large military aircraft, radar installations, housing, and support facilities for personnel in extreme Arctic conditions. Temperatures can drop below −30°C (−22°F), requiring specialized engineering and logistics to sustain operations year-round. The base also supports satellite tracking, space surveillance, and missile warning systems, making it a critical component of U.S. and NATO defense networks. Beyond its military function, Thule has symbolic and practical significance, representing human adaptability in extreme environments and the enduring strategic importance of the Arctic in global security and aerospace monitoring.'),
			('TXT_KEY_BUILDING_THULE_HELP',		''),
			('TXT_KEY_PROMOTION_THULE',			'Operational Range'),
			('TXT_KEY_PROMOTION_THULE_HELP',	'+5%[ICON_RANGE_STRENGTH]Offensive RCS. +2 [ICON_SWAP] Range.');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_THULE_HELP_CUT', '[COLOR_YIELD_FOOD]Thule Air Base[ENDCOLOR] strengthen your air supremacy by keeping more planes in local hangars (+3[ICON_BULLET]Air slots; +2[ICON_SILVER_FIST]), training better pilots (+10 XP to local Planes; +5 XP to global Planes) or improving the overall units capabilities ([COLOR_WATER_TEXT]Operational Range[ENDCOLOR]/[COLOR_YIELD_GOLD]Airplane[ENDCOLOR]).';
				
