-- White Sands Missile Range
INSERT INTO Language_en_US 
			(Tag,									Text)
VALUES		('TXT_KEY_BUILDING_WHITE_SANDS',		'White Sands Missile Range'),
			('TXT_KEY_WONDER_WHITE_SANDS_QUOTE',	'[NEWLINE]"What is pride? A rocket that emulates the stars."[NEWLINE] - William Wordsworth[NEWLINE]'),
			('TXT_KEY_BUILDING_WHITE_SANDS_PEDIA',	'White Sands Missile Range (WSMR), located in southern New Mexico, is the largest military testing area in the United States, with a history dating back to World War II. Established in 1945 on the site of the former Alamogordo Bombing and Gunnery Range, WSMR was created to test rockets, missiles, and other experimental weapons. Its significance was immediately highlighted when the first atomic bomb test, known as the Trinity test, was conducted nearby in July 1945. Over the decades, WSMR has been central to the development and testing of a wide range of military technologies, including guided missiles, ballistic rockets, and missile defense systems, playing a pivotal role in U.S. national defense and aerospace research. [NEWLINE][NEWLINE]The range spans over almost 8300 square kilometres (3200 square miles) of desert terrain, providing a controlled environment for live-fire testing and research. Facilities include launch pads, tracking stations, laboratories, and extensive instrumentation for monitoring tests. WSMR is also home to the White Sands Test Center, which supports both Department of Defense and civilian aerospace projects. The surrounding desert landscape, with its unique gypsum sand dunes, not only offers isolation and safety for testing but also contributes to the site''s distinct geographic identity. Today, White Sands Missile Range continues to serve as a hub for technological innovation, defense research, and training, reflecting its historical importance in advancing military and aerospace capabilities.'),
			('TXT_KEY_BUILDING_WHITE_SANDS_HELP',	''),
			('TXT_KEY_PROMOTION_WHITE_SANDS',		'White Sands Facility'),
			('TXT_KEY_PROMOTION_WHITE_SANDS_HELP',	'+2 [ICON_SWAP] Range.');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_WHITE_SANDS_HELP_CUT', '[COLOR_YIELD_FOOD]White Sands Missile Range[ENDCOLOR] is a facility where numerous tests made rocket engineering reach the highest level ([COLOR_WATER_TEXT]White Sands Facility[ENDCOLOR]/[COLOR_YIELD_GOLD]Missile[ENDCOLOR]; 1 slot for [ICON_SCIENTIST]). Using latest technologies rockets are cheap and easy to manufacture (+33%[ICON_PRODUCTION]/[COLOR_YIELD_GOLD]Missile[ENDCOLOR]; +10%[ICON_PRODUCTION]/[COLOR_YIELD_GOLD]Spaceship Part[ENDCOLOR]; 3 [COLOR_YIELD_GOLD]free Guided Missiles[ENDCOLOR]).';
				
