-- Millau Viaduct
INSERT INTO Language_en_US 
			(Tag,								Text)
VALUES		('TXT_KEY_BUILDING_MILLAU',			'Millau Viaduct'),
			('TXT_KEY_WONDER_MILLAU_QUOTE',		'[NEWLINE]"Above the cloud with its shadow is the star with its light. Above all things reverence thyself."[NEWLINE] - Pythagoras[NEWLINE]'),
			('TXT_KEY_BUILDING_MILLAU_PEDIA',	'The Millau Viaduct, located in southern France, is a cable-stayed bridge that spans the Tarn River valley near the town of Millau in the Aveyron region. Its construction was completed in 2004, designed by French structural engineer Michel Virlogeux and British architect Norman Foster. The project was conceived to improve traffic flow on the A75 motorway, which connects Paris to the Mediterranean, and to bypass the congested town of Millau. At the time of its completion, the viaduct became the tallest bridge in the world, with one of its pylons reaching a height of 343 meters (1,125 feet), surpassing the height of the Eiffel Tower. The bridge was celebrated as an engineering marvel, combining innovative structural design with aesthetic elegance. [NEWLINE][NEWLINE]The Millau Viaduct is characterized by its slender, soaring towers and streamlined roadway supported by a series of cable stays, which allow it to span 2,460 meters (8,070 feet) across the Tarn Valley. Its design emphasizes both strength and minimal visual impact, blending harmoniously with the surrounding landscape. The roadway is elevated above the valley, providing breathtaking views and efficient travel across the region. Beyond its functional role in transportation, the Millau Viaduct has become a symbol of modern engineering excellence and architectural beauty, attracting tourists, engineers, and enthusiasts worldwide who admire its combination of technical achievement and elegant design.'),
			('TXT_KEY_BUILDING_MILLAU_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_MILLAU_HELP_CUT', '[COLOR_YIELD_FOOD]Millau Viaduct[ENDCOLOR] connects two sides of valley very difficult to pass without such construction, making life of local and more distant citizens (-3[ICON_HAPPINESS_3] Urbanization; +1[ICON_HAPPINESS_1]) or tourists (+5%[ICON_TOURISM][ICON_TOURISM]; 5%[ICON_PRODUCTION] into [ICON_TOURISM]) much easier. It also serves as a new shorter way of transporting goods in your country ([ICON_CARAVAN]: +100%[ICON_SWAP]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Terrain: [COLOR_NEGATIVE_TEXT]Coast[ENDCOLOR][NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR][NEWLINE][ICON_BULLET]Improvement: [COLOR_CYAN]Village[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_MILLAU_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Plot: [COLOR_CYAN]Hill[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_MILLAU_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
