-- Revolutionary Museum
INSERT INTO Language_en_US 
			(Tag,											Text)
VALUES		('TXT_KEY_BUILDING_REVOLUTIONARY_MUSEUM',		'Revolutionary Museum'),
			('TXT_KEY_WONDER_REVOLUTIONARY_MUSEUM_QUOTE',	'[NEWLINE]"The oppressed peoples can liberate themselves only through struggle. This is a simple and clear truth confirmed by history."[NEWLINE] - Kim Il-sung[NEWLINE]'),
			('TXT_KEY_BUILDING_REVOLUTIONARY_MUSEUM_PEDIA',	'The Korean Revolution Museum, located at the foot of Mansu Hill in Pyongyang, North Korea, was first established in 1948 and later expanded in 1960. It stands as one of the largest museums in the country, built to commemorate and narrate the revolutionary history of North Korea under the leadership of Kim Il Sung and Kim Jong Il. The museum showcases North Korea''s official version of its history, beginning with the anti-Japanese resistance struggles of the early 20th century, through the Korean War (1950–1953), and into the development of the socialist state. Its structure and size reflect its symbolic importance, with vast exhibition halls designed to project grandeur and revolutionary pride. [NEWLINE][NEWLINE]Inside, the museum houses dozens of exhibition rooms containing artifacts, photographs, documents, dioramas, and large-scale displays. These exhibits are carefully curated to emphasize the leadership and legacy of the Kim family, portraying them as central to every major historical event. Visitors encounter narratives that blend history with ideology, highlighting themes of struggle, sacrifice, and national unity. The Korean Revolution Museum serves both as a historical institution and as a political tool, reinforcing the state''s official ideology, Juche, and cultivating loyalty to the ruling family. It continues to be a required destination for North Korean citizens on organized visits, as well as a tightly controlled site for foreign tourists.'),
			('TXT_KEY_BUILDING_REVOLUTIONARY_MUSEUM_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_REVOLUTIONARY_MUSEUM_HELP_CUT', '[COLOR_YIELD_FOOD]Revolutionary Museum[ENDCOLOR] praise your civilization''s leaders like Gods (+3[ICON_CULTURE]/all [COLOR_YIELD_FOOD]Monuments[ENDCOLOR]; 50[ICON_CULTURE]/[ICON_GREAT_PEOPLE] expend; [COLOR_MAGENTA]free Policy[ENDCOLOR]). There''s also much higher chance to have a worthy successor on his place (+10%[ICON_GREAT_PEOPLE][ICON_GREAT_PEOPLE]). All security services do everything to show people from all over the world the most important parts of your country (+2[ICON_TOURISM]/all [COLOR_YIELD_FOOD]Police Stations[ENDCOLOR], [COLOR_YIELD_FOOD]Constabularies[ENDCOLOR]).';
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_UNIT_TEXT]Order[ENDCOLOR][NEWLINE][ICON_BULLET]Building: [COLOR_CYAN]Broadcast Tower[ENDCOLOR], [COLOR_CYAN]Police Station[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_REVOLUTIONARY_MUSEUM_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Special: [COLOR_UNIT_TEXT]Order[ENDCOLOR][NEWLINE][ICON_BULLET]Building: [COLOR_CYAN]Broadcast Tower[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_REVOLUTIONARY_MUSEUM_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);
