-- Three Gorges Dam
INSERT INTO Language_en_US 
			(Tag,											Text) 
VALUES		('TXT_KEY_BUILDING_THREE_GORGES_DAM',			'Three Gorges Dam'),
			('TXT_KEY_WONDER_THREE_GORGES_DAM_QUOTE',		'[NEWLINE]"Walls of stone will stand upstream to the west[NEWLINE]To hold back Wushan''s clouds and rain[NEWLINE]Till a smooth lake rises in the narrow gorges.[NEWLINE]The mountain goddess if she is still there[NEWLINE]Will marvel at a world so changed."[NEWLINE] - "Swimming", Mao Zedong[NEWLINE]'),
			('TXT_KEY_BUILDING_THREE_GORGES_DAM_PEDIA',		'The Three Gorges Dam, located on the Yangtze River in Hubei Province, China, is the world''s largest hydroelectric power station by installed capacity. The project was first envisioned as early as the 1910s by Chinese leaders and engineers, but political instability and limited resources delayed its realization. Serious planning resumed after the founding of the People''s Republic of China, and construction officially began in 1994. The dam was structurally completed in 2006, with its full generating capacity achieved by 2012. It represents one of the most ambitious engineering projects in modern history, intended not only to generate electricity but also to control flooding along the Yangtze and improve river navigation.[NEWLINE][NEWLINE]The dam stretches over 2.3 kilometers across the Yangtze River and rises about 185 meters in height, creating a reservoir that extends more than 600 kilometers upstream. Its 34 generating turbines give it a capacity of 22,500 megawatts, supplying power to millions of households across China. While the project has brought significant economic and energy benefits, it has also been controversial due to its environmental and social impacts. The reservoir submerged hundreds of towns and villages, forcing the relocation of over a million people, and it has altered ecosystems and cultural sites along the river valley. Today, the Three Gorges Dam stands as both a symbol of China''s engineering prowess and a focal point of debate about the balance between large-scale development and its human and ecological costs.'),
			('TXT_KEY_BUILDING_THREE_GORGES_DAM_HELP',		'');

INSERT INTO Language_en_US (Tag, Text) 
VALUES ('TXT_KEY_BUILDING_THREE_GORGES_DAM_HELP_CUT', 'Monumental [COLOR_YIELD_FOOD]Three Gorges Dam[ENDCOLOR] is an enormous effort of qualified engineers (2 slots for [ICON_ENGINEER]; +1[ICON_RESEARCH]/[ICON_ENGINEER][ICON_ENGINEER]). This huge [COLOR_YIELD_FOOD]Hydroelectric Power Plant[ENDCOLOR] ([COLOR_YIELD_FOOD]free[ENDCOLOR]) supports local economy based on [COLOR_CITY_GREEN]River[ENDCOLOR] and [COLOR_CITY_GREEN]Lakes[ENDCOLOR] (+1[ICON_PRODUCTION]/[COLOR_CITY_GREEN]Tile[ENDCOLOR]; 200% of city''s [ICON_GOLD] is added to their current [ICON_GOLD] on [ICON_CITIZEN] Birth)');
				
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]River[ENDCOLOR][NEWLINE][ICON_BULLET]Building: [COLOR_NEGATIVE_TEXT]Power Plant[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_THREE_GORGES_DAM_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=2);	
UPDATE Language_en_US SET Text = 'All requirements (including lua):[NEWLINE][ICON_BULLET]Feature: [COLOR_CYAN]River[ENDCOLOR][NEWLINE][ICON_BULLET]Building: [COLOR_NEGATIVE_TEXT]Power Plant[ENDCOLOR]'||Text WHERE Tag ='TXT_KEY_BUILDING_THREE_GORGES_DAM_HELP' AND EXISTS (SELECT * FROM COMMUNITY WHERE Type='MW-SETTING-REQUIREMENT' AND Value=1);	
