-- Taipei 101
INSERT INTO Language_en_US 
			(Tag,								Text)
VALUES		('TXT_KEY_BUILDING_TAIPEI',			'Taipei 101'),
			('TXT_KEY_WONDER_TAIPEI_QUOTE',		'[NEWLINE]"Everything is designed. Few things are designed well."[NEWLINE] - Brian Reed[NEWLINE]'),
			('TXT_KEY_BUILDING_TAIPEI_PEDIA',	'Taipei 101, located in the Xinyi District of Taipei, Taiwan, is a landmark skyscraper that held the title of the world''s tallest building from 2004 to 2010. Its construction began in 1999 and was completed in 2004, designed by Taiwanese architect C.Y. Lee in collaboration with structural engineers to withstand Taiwan''s frequent earthquakes and typhoons. Taipei 101 was conceived as both a symbol of modern Taiwan and a representation of traditional Asian values, blending contemporary design with elements inspired by bamboo stalks, which signify growth and resilience. The building became a focal point for economic development and international recognition, reflecting Taiwan''s ambitions in finance, commerce, and sustainable architecture. [NEWLINE][NEWLINE]Standing 508 meters (1,667 feet) tall with 101 floors above ground and 5 underground, Taipei 101 features a unique postmodern design with a multi-level pagoda-like shape. The building incorporates advanced engineering technologies, including a massive tuned mass damper that stabilizes it during high winds and earthquakes. Taipei 101 houses offices, retail spaces, restaurants, and an observatory that offers panoramic views of Taipei City. Beyond its functional use, it has become a cultural and tourist icon, hosting New Year''s Eve fireworks and events, and symbolizing Taiwan''s technological innovation, architectural excellence, and global presence.'),
			('TXT_KEY_BUILDING_TAIPEI_HELP',	'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_TAIPEI_HELP_CUT', '[COLOR_YIELD_FOOD]Taipei 101[ENDCOLOR] is a huge challenge for engineers (+1[ICON_RESEARCH]/[ICON_ENGINEER][ICON_ENGINEER]). It serves as a diplomatic point (+1[ICON_DIPLOMAT] League Vote), business center (+2[ICON_GOLD]/all [COLOR_YIELD_FOOD]Banks[ENDCOLOR], [COLOR_YIELD_FOOD]Stock Exchanges[ENDCOLOR]) and commercial hub connecting local [COLOR_CITY_BROWN]Villages[ENDCOLOR] and [COLOR_CITY_BROWN]Towns[ENDCOLOR] together (+2[ICON_GOLD]/Tile).';
				
