-- Global Positioning System
INSERT INTO Language_en_US 
			(Tag,								Text)
VALUES		('TXT_KEY_BUILDING_GPS',			'Global Positioning System'),
			('TXT_KEY_WONDER_GPS_QUOTE',		'[NEWLINE]"Unknown airport with Cessna 150 circling overhead, identify yourself."[NEWLINE] - George W. Stewart[NEWLINE]'),
			('TXT_KEY_BUILDING_GPS_PEDIA',		'The Global Positioning System (GPS) is a satellite-based navigation system developed by the United States Department of Defense. Its origins trace back to the 1970s, when the U.S. military sought a reliable way to provide accurate positioning, navigation, and timing information anywhere on Earth. The first experimental GPS satellite was launched in 1978, and by the mid-1990s the system became fully operational with a constellation of 24 satellites orbiting the Earth. While initially intended for military use, GPS was opened to civilian applications in the 1980s, eventually becoming a critical infrastructure for global transportation, communication, and commerce. [NEWLINE][NEWLINE]GPS works by using signals transmitted from satellites to receivers on the ground, which calculate the user''s exact location based on the time it takes for the signals to arrive. The system provides highly accurate data for positioning, navigation, and timing, supporting industries such as aviation, maritime navigation, agriculture, surveying, and everyday smartphone applications. Over time, technological advances have improved the precision of GPS, reducing errors from several meters to mere centimeters when combined with augmentation systems. Today, GPS is one of several global navigation satellite systems (GNSS), but it remains the most widely used, underpinning both civilian life and military operations worldwide.'),
			('TXT_KEY_BUILDING_GPS_HELP',		'');
			
INSERT INTO Language_en_US (Tag, Text) 
SELECT 'TXT_KEY_BUILDING_GPS_HELP_CUT', '[COLOR_YIELD_FOOD]Global Positioning System[ENDCOLOR] helps you maintain security in your country (+200[ICON_SPY_POINT]; +20[ICON_SPY][ICON_SPY] City Security). Both, your attacks (25[ICON_GREAT_GENERAL], 25[ICON_GREAT_ADMIRAL]/[ICON_SPY] Attack) and defense (50[ICON_PRODUCTION], 50[ICON_GOLD]/[ICON_SPY] Defense) are generously rewarded.';
				
